INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('300cfee12be8c0ad', 'standard-fijian', 'word', 'keirau', 'keirau', 'pronoun', 'we two, excluding you (subject use)', '', '', '', 'Founder-supplied subject use of an isosomi form. Durusau describes its role only when it marks the subject within a matavu; a Fijian phrase remains to be checked. Attached form -irau appears in neirau.', '{"role":{"fijian":"isosomi","english":"first-person pronoun in subject use; durusau only within a matavu"},"relatedWords":["kedaru"],"comparison":"Keirau excludes the listener; kedaru/daru includes the listener. Keirau is dual (two people). Attached form -irau appears in neirau.","furtherLink":{"label":"Explore keirau in Object licensing in Fijian and the role of adjacency (2019)","href":"https://link.springer.com/article/10.1007/s11049-019-09442-1"},"quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"Founder-supplied subject use of an isosomi form. Durusau describes its role only when it marks the subject within a matavu; a Fijian phrase remains to be checked. Attached form -irau appears in neirau."}}', '[{"sourceId":"naisema-founder-pronouns-2026-11-01"},{"sourceId":"fijian-object-licensing-2019"},{"sourceId":"fijian-pronoun-paradigm-study"},{"sourceId":"6c1d945a54cd","page":11}]', '["pronouns"]', 'keirau | we two, excluding you (subject use) | |', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
