INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('f506a57c038284f7', 'standard-fijian', 'word', 'keitou', 'keitou', 'pronoun', 'we few, including a group of three, excluding you (subject use)', '', '', '', 'Founder-supplied subject use of an isosomi form. Durusau describes its role only when it marks the subject within a matavu; a Fijian phrase remains to be checked. Attached form -itou appears in neitou; it is exclusive.', '{"role":{"fijian":"isosomi","english":"first-person pronoun in subject use; durusau only within a matavu"},"relatedWords":["keimami","kedatou"],"comparison":"Keitou excludes the listener and is paucal (a few people); keimami is plural (many). Attached form -itou appears in neitou; it is exclusive.","furtherLink":{"label":"Explore keitou in Object licensing in Fijian and the role of adjacency (2019)","href":"https://link.springer.com/article/10.1007/s11049-019-09442-1"},"quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"Founder-supplied subject use of an isosomi form. Durusau describes its role only when it marks the subject within a matavu; a Fijian phrase remains to be checked. Attached form -itou appears in neitou; it is exclusive."}}', '[{"sourceId":"naisema-founder-pronouns-2026-11-01"},{"sourceId":"fijian-object-licensing-2019"},{"sourceId":"fijian-pronoun-paradigm-study"},{"sourceId":"6c1d945a54cd","page":11}]', '["pronouns"]', 'keitou | we few, including a group of three, excluding you (subject use) | |', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
