INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('3bac971fde332f55', 'standard-fijian', 'grammar-term', 'dewa', 'dewa', '', 'An ending attached to some predicate bases when an affected person or thing is expressed, such as -a in raica.', '', 'A dewa attaches after some vu bases and relates the predicate to a person or thing affected. Dewa endings have short and long families. Record the full form and its participant in a sentence; the ending cannot be selected from English alone.', '', 'Fijian grammar term from the supplied visual guide. English labels explain the role approximately; check a complete phrase before approving.', '{"comparison":"The dewa is the ending; the koso dewa is a connecting consonant before it, such as c in raica. A dewa form changes the participant pattern, not simply the tense.","grammarFunction":"An ending attached to some predicate bases when an affected person or thing is expressed, such as -a in raica.","grammarGroup":"Predicate phrase","grammarExample":"Au raica tiko na gone.","tables":[{"title":"Dewa forms","columns":["Family","Ending","Example form","Check"],"rows":[["dewaleka","-a","mokuta","base and affected participant"],["dewaleka","-i","mokuti","base and affected participant"],["dewabalavu","-aka","mokulaka","meaning in its own phrase"],["dewabalavu","-aki","mokulaki","meaning in its own phrase"]],"note":"These forms are examples, not a rule for generating new words."}],"quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"Fijian grammar term from the supplied visual guide. English labels explain the role approximately; check a complete phrase before approving."}}', '[{"sourceId":"534756bd7910","page":3},{"sourceId":"tuvavosa-4-4-4-5-photos-2026-10-31","section":"4.4.1–4.4.3"}]', '[]', 'dewa | an ending attached to some predicate bases when an affected person or thing is expressed, such as -a in raica. | | a dewa attaches after some vu bases and relates the predicate to a person or thing affected. dewa endings have short and long families. record the full form and its participant in a sentence; the ending cannot be selected from english alone.', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('c7f9b3159053928f', 'standard-fijian', 'grammar-term', 'drua', 'drua', '', 'Repetition of all or part of a word base to make a related form; the new meaning must be checked in context.', '', 'Repeating a syllable or larger part of a base can mark iteration, plurality or other word-forming functions.', '', 'Fijian grammar term from the supplied visual guide. English labels explain the role approximately; check a complete phrase before approving. The Tuvavosa examples contrast short and longer repetition, including kekeli and culacula. Schütz independently describes full and partial reduplication with several functions; individual derivatives still need their own checked meanings.', '{"comparison":"Drualeka repeats a shorter part; druabalavu repeats a longer part. Repetition does not have one automatic English meaning.","grammarFunction":"Repetition of all or part of a word base to make a related form; the new meaning must be checked in context.","grammarGroup":"Word building and roles","grammarExample":"Au culacula tiko.","furtherLink":{"label":"Explore drua in Albert J. Schütz, The Fijian Language, chapter 18","href":"https://manifold.uhpress.hawaii.edu/projects/the-fijian-language"},"quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"Fijian grammar term from the supplied visual guide. English labels explain the role approximately; check a complete phrase before approving. The Tuvavosa examples contrast short and longer repetition, including kekeli and culacula. Schütz independently describes full and partial reduplication with several functions; individual derivatives still need their own checked meanings."}}', '[{"sourceId":"534756bd7910","page":4},{"sourceId":"schutz-fijian-language-reduplication"}]', '[]', 'drua | repetition of all or part of a word base to make a related form; the new meaning must be checked in context. | | repeating a syllable or larger part of a base can mark iteration, plurality or other word-forming functions.', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('93fc371f0c139a41', 'standard-fijian', 'grammar-term', 'duru', 'duru', '', 'A marker or particle around the yavu in a matavosa that marks an actor, aspect, direction, or another grammatical relationship.', '', 'An element that adds to or limits the meaning around a yavu; it may appear before or after it.', '', 'Fijian grammar term from the supplied visual guide. English labels explain the role approximately; check a complete phrase before approving.', '{"role":{"fijian":"durusau","english":"actor marker"},"usageExamples":[{"fijian":"Au sa lako yani.","english":"I am going away.","words":[{"text":"Au","role":"durusau","english":"actor marker","focus":true},{"text":"sa","role":"durugauna","english":"aspect marker","focus":true},{"text":"lako","role":"yavu / vu","english":"predicate base"},{"text":"yani","role":"durumuri","english":"following direction particle","focus":true}],"punctuation":"."}],"comparison":"In Au sa lako yani, au (durusau) and sa (durugauna) come before the yavu lako; yani (durumuri) follows it. The yavu carries the core meaning; the duru shape its use.","grammarFunction":"A marker or particle around the yavu in a matavosa that marks an actor, aspect, direction, or another grammatical relationship.","grammarGroup":"Building blocks","grammarExample":"rau · sa · na · tiko · mai","marker":{"kind":"Duru","forms":"au · sa · yani","position":"Before or after the yavu within a matavu.","note":"In Au sa lako yani, au points to the actor, sa marks the predicate, and yani adds direction."},"furtherLink":{"label":"Explore duru in Sangam Education Society · Year 9 Fijian worksheet","href":"https://sangamedu.ac.fj/wp-content/uploads/2021/07/Home-Study-Package-Year-9.pdf"},"quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"Fijian grammar term from the supplied visual guide. English labels explain the role approximately; check a complete phrase before approving."}}', '[{"sourceId":"534756bd7910","page":1},{"sourceId":"sangam-year9-tuvavosa-2021"}]', '[]', 'duru | a marker or particle around the yavu in a matavosa that marks an actor, aspect, direction, or another grammatical relationship. | | an element that adds to or limits the meaning around a yavu; it may appear before or after it.', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('b43bf2f39021b7c2', 'standard-fijian', 'grammar-term', 'durugauna', 'durugauna', '', 'A duru that marks time, state, or aspect, such as sa in Au sa lako yani.', '', 'A preverbal marker involving time, state, expectation or sequence; examples include a, sa, se, na and qai. Dialect and context matter.', '', 'Fijian grammar term from the supplied visual guide. English labels explain the role approximately; check a complete phrase before approving. The photographed Tuvavosa explanation and an independent Year 13 teaching text identify durugauna as a type of duruliu. A particular marker''s reading still depends on its full phrase.', '{"comparison":"Durugauna helps mark time, state, or aspect, as sa does in Au sa lako yani. Durusau identifies the actor or subject, as au does there.","grammarCode":"dg","grammarFunction":"Time, state, or aspect marker","grammarGroup":"Predicate phrase","grammarExample":"Keirau sa na lako.","marker":{"kind":"Duru","forms":"sa · a · na · se (examples)","position":"Before the yavu, after the durusau when both occur.","note":"This duru marks time, state, or aspect in context."},"furtherLink":{"label":"Explore durugauna in Nanuma Lesu Na Noda Vosa 13 - Tuvavosa exercises, page 87","href":"https://fliphtml5.com/gjgbb/elah/Year_13_Nanuma_Lesu_Na_Noda_Vosa_13/87/"},"quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"Fijian grammar term from the supplied visual guide. English labels explain the role approximately; check a complete phrase before approving. The photographed Tuvavosa explanation and an independent Year 13 teaching text identify durugauna as a type of duruliu. A particular marker''s reading still depends on its full phrase."}}', '[{"sourceId":"534756bd7910","page":3},{"sourceId":"nanuma-lesu-year13-durugauna"}]', '[]', 'durugauna | a duru that marks time, state, or aspect, such as sa in au sa lako yani. | | a preverbal marker involving time, state, expectation or sequence; examples include a, sa, se, na and qai. dialect and context matter.', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('c2bffc5b377c2283', 'standard-fijian', 'grammar-term', 'duruliu', 'duruliu', '', 'A duru that comes before the yavu of a matavu, such as au and sa before lako in Au sa lako yani.', '', 'A positional family of elements before the main yavu of a matavu. Isema comes first when present, then durusau, followed by durugauna and other earlier particles. Do not treat duruliu as one English word class or assume every member appears in each phrase.', '', 'This explanation and its use in a complete Fijian phrase need team review.', '{"comparison":"Duruliu come before the yavu of a matavu; in Au sa lako yani, au and sa precede lako. Durumuri follow the yavu, as yani does.","grammarCode":"dl","grammarFunction":"Particle before the predicate base","grammarGroup":"Predicate phrase","grammarExample":"se ra sa yaco mai","marker":{"kind":"Duru","forms":"isema · durusau · durugauna","position":"Before the yavu of a matavu.","note":"These are different jobs within the earlier part of the predicate phrase."},"furtherLink":{"label":"Explore duruliu in ANU: Surface order in the Standard Fijian verb phrase","href":"https://openresearch-repository.anu.edu.au/bitstreams/86dd578b-ce08-4a6a-902b-302e765e5286/download"},"quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"Tuvavosa teaching explanation checked against the supplied printed scan and independent research. Phrase wording and contextual role still need team review."}}', '[{"sourceId":"tuvavosa-review-scan-2026-10-30","page":24,"section":"4.1-4.2"},{"sourceId":"anu-fijian-verb-phrase-surface-order"}]', '[]', 'duruliu | a duru that comes before the yavu of a matavu, such as au and sa before lako in au sa lako yani. | | a positional family of elements before the main yavu of a matavu. isema comes first when present, then durusau, followed by durugauna and other earlier particles. do not treat duruliu as one english word class or assume every member appears in each phrase.', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('b29c96cdcdd6f60f', 'standard-fijian', 'grammar-term', 'durumuri', 'durumuri', '', 'A duru that follows the yavu of a matavu, such as yani after lako in Au sa lako yani.', '', 'Durumuri follow the earlier yavu and kilavu position in a matavu. Several can occur together, but their order and compatibility depend on the forms and meaning. The order distinguishes distribution before a later limiting form, joint action before direction, and direction before continuation. The same spelling can instead serve as a vu, kilavu, kilanauni or another role in another phrase.', '', 'This explanation and its use in a complete Fijian phrase need team review.', '{"comparison":"Durumuri come after the yavu; in Au sa lako yani, yani follows lako. Duruliu, such as au and sa here, come before it.","grammarCode":"dm","grammarFunction":"Particle after the predicate base","grammarGroup":"Predicate phrase","grammarExample":"Sā curuma cake tiko.","marker":{"kind":"Duru","forms":"tiko · yani · mai · mada (examples)","position":"After the yavu and any intervening allowed elements.","note":"These forms may add continuation, direction, or other meanings; each has its own role."},"tables":[{"title":"Durumuri · order contrasts","columns":["Source accepts","Source rejects in this contrast","Check"],"rows":[["mo liu taudua gā","*mo liu gā taudua","distribution before later limiting form"],["era yabe vata yani","*era yabe yani vata","joint action before direction"],["sā curuma cake tiko","*sā curuma tiko cake","direction before continuation"]],"note":"An asterisk marks an excluded order for that contrast. Other varieties and meanings require separate evidence."}],"furtherLink":{"label":"Explore durumuri in ANU: Surface order in the Standard Fijian verb phrase","href":"https://openresearch-repository.anu.edu.au/bitstreams/86dd578b-ce08-4a6a-902b-302e765e5286/download"},"quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"Tuvavosa teaching explanation checked against the supplied printed scan and independent research. Phrase wording and contextual role still need team review."}}', '[{"sourceId":"tuvavosa-review-scan-2026-10-30","page":24,"section":"4.1.1; 4.5.4-4.5.5"},{"sourceId":"anu-fijian-verb-phrase-surface-order"},{"sourceId":"tuvavosa-4-4-4-5-photos-2026-10-31","section":"4.5.4–4.5.5"}]', '[]', 'durumuri | a duru that follows the yavu of a matavu, such as yani after lako in au sa lako yani. | | durumuri follow the earlier yavu and kilavu position in a matavu. several can occur together, but their order and compatibility depend on the forms and meaning. the order distinguishes distribution before a later limiting form, joint action before direction, and direction before continuation. the same spelling can instead serve as a vu, kilavu, kilanauni or another role in another phrase.', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('766cf71e5948b728', 'standard-fijian', 'grammar-term', 'durusau', 'durusau', '', 'The duru that identifies the actor or subject by person and number, such as au in Au sa lako yani.', '', 'The first duru after isema in a matavu. It marks the sau (actor/subject participant) by person and number, although it may not be spoken in some contexts. Initial o/e may be omitted in some non-command sentences and drops in commands; after short isema se, ni, me, de, ke, initial e drops while o does not follow the same rule. First-person singular after those connectors is u rather than au. Distinguish these forms from independent nauni sosomi.', '', 'This explanation and its use in a complete Fijian phrase need team review.', '{"comparison":"Durusau identifies the actor or subject by person and number. Durugauna marks time, state, or aspect; in Au sa lako yani, au and sa do these different jobs.","grammarCode":"ds","grammarFunction":"Actor or subject-reference marker","grammarGroup":"Predicate phrase","grammarExample":"se ra sa yaco mai; me da tekivu","marker":{"kind":"Duru","forms":"au · o · e · rau · ratou · era (examples)","position":"Before the yavu, following an isema when one occurs.","note":"This duru identifies the participant by person and number."},"tables":[{"title":"Durusau · VR person and number","columns":["Wiliwili · number","Qo · speaker, listener excluded","Qori · listener","Ya · third person","Okati · speaker and listener"],"rows":[["Dua · one","au / u after a short connector","o","e","—"],["Rua · two","keirau","(o)drau","(e)rau","(e)daru"],["Vica · a few","keitou","(o)dou","(e)ratou","(e)(da)tou"],["Levu · many","keimami","(o)ni","(e)ra","(e)da"]],"note":"Parentheses mark context-dependent omission, not free interchange. In commands the initial o/e drops; at the start of some non-commands it may drop; after short isema se, ni, me, de, ke the initial e drops but o does not follow the same rule. After those connectors first-person singular is u, not au. The inclusive column has no singular."}],"furtherLink":{"label":"Explore durusau in ANU thesis: Standard Fijian pronoun paradigm (Table 7.2)","href":"https://openresearch-repository.anu.edu.au/bitstreams/ad8ffd53-3125-4166-885e-a761ec8bf989/download"},"quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"Tuvavosa teaching explanation checked against the supplied printed scan and independent research. Phrase wording and contextual role still need team review."}}', '[{"sourceId":"tuvavosa-review-scan-2026-10-30","page":25,"section":"4.1.3"},{"sourceId":"fijian-pronoun-paradigm-study"},{"sourceId":"anu-fijian-verb-phrase-surface-order"}]', '[]', 'durusau | the duru that identifies the actor or subject by person and number, such as au in au sa lako yani. | | the first duru after isema in a matavu. it marks the sau (actor/subject participant) by person and number, although it may not be spoken in some contexts. initial o/e may be omitted in some non-command sentences and drops in commands; after short isema se, ni, me, de, ke, initial e drops while o does not follow the same rule. first-person singular after those connectors is u rather than au. distinguish these forms from independent nauni sosomi.', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('1a230dd64d8c2c12', 'standard-fijian', 'grammar-term', 'ikurau', 'ikurau', '', 'An exclamation that can stand apart from ordinary phrase building, such as Isa! or Sobo!', '', 'An expressive form that can stand outside ordinary extended phrase building.', '', 'Fijian grammar term from the supplied visual guide. English labels explain the role approximately; check a complete phrase before approving. The photographed Tuvavosa category and the independent Year 9 textbook both treat ikurau as an expressive utterance; they do not make every interjection equivalent in feeling.', '{"comparison":"Ikurau expresses a reaction. Duru is a supporting element within a matavosa, placed around its yavu.","grammarFunction":"An exclamation that can stand apart from ordinary phrase building, such as Isa! or Sobo!","grammarGroup":"Building blocks","grammarExample":"Isa!","furtherLink":{"label":"Explore ikurau in Nanuma Lesu Na Noda Vosa 9 - Year 9 textbook, page 31","href":"https://beaconmedia.com.au/beaconmedia/wp-content/uploads/2025/09/Yr-9-NANUMALESUNANODAVOSA9StudentsTextbook.pdf"},"quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"Fijian grammar term from the supplied visual guide. English labels explain the role approximately; check a complete phrase before approving. The photographed Tuvavosa category and the independent Year 9 textbook both treat ikurau as an expressive utterance; they do not make every interjection equivalent in feeling."}}', '[{"sourceId":"534756bd7910","page":1},{"sourceId":"nanuma-lesu-year9-ikurau"}]', '[]', 'ikurau | an exclamation that can stand apart from ordinary phrase building, such as isa! or sobo! | | an expressive form that can stand outside ordinary extended phrase building.', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('5e6885a3e5a573f1', 'standard-fijian', 'grammar-term', 'ikuriliu', 'ikuriliu', '', 'A prefix attached before a word base, as vei- is in veivosaki.', '', 'A word-building addition, not a separate matanauni marker. In section 3.4.2, vei- with some nauni can form collective or place-related nouns; dau- with a vu or nauni can form a noun for a habitual or skilled person; i- with a vu can form nouns for tools, products, acts, activities, places or remnants. Check each derived word: the same prefix has other uses in other constructions.', '', 'Check this meaning and its use in a complete Fijian phrase before approving it.', '{"comparison":"Ikuriliu attaches before a base; ikurimuri attaches after it. Position alone does not tell us the new word''s meaning.","grammarFunction":"A prefix attached before a word base, as vei- is in veivosaki.","grammarGroup":"Word building and roles","grammarExample":"Rau sa veidomoni.","furtherLink":{"label":"Explore ikuriliu in Sangam Education Society · Year 9 Fijian worksheet","href":"https://sangamedu.ac.fj/wp-content/uploads/2021/07/Home-Study-Package-Year-9.pdf"},"quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"Fijian grammar term from the supplied visual guide. English labels explain the role approximately; check a complete phrase before approving. The photographed source and Sangam Year 9 teaching sheet both identify a piece before the base. A specific derived form still needs its own checked meaning."}}', '[{"sourceId":"tuvavosa-review-scan-2026-10-30","section":"3.4.2"},{"sourceId":"534756bd7910","page":4},{"sourceId":"sangam-year9-tuvavosa-2021"}]', '[]', 'ikuriliu | a prefix attached before a word base, as vei- is in veivosaki. | | a word-building addition, not a separate matanauni marker. in section 3.4.2, vei- with some nauni can form collective or place-related nouns; dau- with a vu or nauni can form a noun for a habitual or skilled person; i- with a vu can form nouns for tools, products, acts, activities, places or remnants. check each derived word: the same prefix has other uses in other constructions.', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('e534c679c5bb1181', 'standard-fijian', 'grammar-term', 'ikurimuri', 'ikurimuri', '', 'A suffix attached after a word base; its exact effect depends on the complete word.', '', 'A bound element added after a base, including some transitive endings and possessed-noun suffixes.', '', 'Check this meaning and its use in a complete Fijian phrase before approving it.', '{"comparison":"Ikurimuri attaches after a base; ikuriliu attaches before it. Ikuri sosomi is a narrower attached person-and-number ending.","grammarFunction":"A suffix attached after a word base; its exact effect depends on the complete word.","grammarGroup":"Word building and roles","grammarExample":"Na yavaqu.","furtherLink":{"label":"Explore ikurimuri in Sangam Education Society · Year 9 Fijian worksheet","href":"https://sangamedu.ac.fj/wp-content/uploads/2021/07/Home-Study-Package-Year-9.pdf"},"quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"Fijian grammar term from the supplied visual guide. English labels explain the role approximately; check a complete phrase before approving. The photographed source and Sangam Year 9 teaching sheet both identify the position after the base. This is a word part, not a label assigned from an English translation."}}', '[{"sourceId":"534756bd7910","page":4},{"sourceId":"sangam-year9-tuvavosa-2021"}]', '[]', 'ikurimuri | a suffix attached after a word base; its exact effect depends on the complete word. | | a bound element added after a base, including some transitive endings and possessed-noun suffixes.', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('0d3d38706f8c6ddd', 'standard-fijian', 'grammar-term', 'isema', 'isema', '', 'A connector that links a clause or predicate phrase to another part of the sentence, such as ia, se, baleta, or kevaka.', '', 'The first kind of duruliu. A matavu can have zero, one, or two isema. With two, a first-set form (ia, se, baleta, kevaka) precedes a second-set form (ni, me, de, ke). Check the actual clause; the order alone does not establish its meaning.', '', 'This explanation and its use in a complete Fijian phrase need team review.', '{"comparison":"Isema joins clauses or ideas. Mata introduces a matanauni; the same short spelling may need a different analysis in another sentence.","grammarFunction":"A connector that links a clause or predicate phrase to another part of the sentence, such as ia, se, baleta, or kevaka.","grammarGroup":"Predicate phrase","grammarExample":"se me keirau lako","marker":{"kind":"Duru","forms":"ia · se · baleta · kevaka · ni · me · de · ke","position":"At the start of the matavu when it connects clauses or ideas.","note":"If two occur, their order depends on the isema groups."},"tables":[{"title":"Isema · two ordered sets","columns":["First isema","Second isema","Short phrase from this pattern"],"rows":[["ia","ni","Ia ni ra sa yaco yani kina"],["se","me","se me keirau lako"],["baleta","ni","Baleta ni sega tiko"],["kevaka","me","Kevaka me a tatau vakavinaka"]],"note":"First-set choices: ia, se, baleta, kevaka. Second-set choices: ni, me, de, ke. A matavu may have zero, one, or two isema. The table illustrates order, not every possible pairing or meaning. Example wording needs team review."}],"furtherLink":{"label":"Explore isema in ANU: Surface order in the Standard Fijian verb phrase","href":"https://openresearch-repository.anu.edu.au/bitstreams/86dd578b-ce08-4a6a-902b-302e765e5286/download"},"quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"Tuvavosa teaching explanation checked against the supplied printed scan and independent research. Phrase wording and contextual role still need team review."}}', '[{"sourceId":"tuvavosa-review-scan-2026-10-30","page":24,"section":"4.1.2"},{"sourceId":"anu-fijian-verb-phrase-surface-order"}]', '[]', 'isema | a connector that links a clause or predicate phrase to another part of the sentence, such as ia, se, baleta, or kevaka. | | the first kind of duruliu. a matavu can have zero, one, or two isema. with two, a first-set form (ia, se, baleta, kevaka) precedes a second-set form (ni, me, de, ke). check the actual clause; the order alone does not establish its meaning.', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('ad083ad7177d685c', 'standard-fijian', 'grammar-term', 'iyatuvosa', 'iyatuvosa', '', 'sentence built from interacting phrases', '', 'An iyatuvosa is a whole sentence built from interacting phrases. First decide whether its construction is predicate-based, nominal, or another attested type. In a predicate sentence, check the internal matavu order, then identify any matanauni that specifies a participant outside that narrower phrase. Its position in the whole sentence needs an attested example; one English word order or one Fijian example is not a universal template.', '', 'Fijian grammar term from the supplied visual guide. English labels explain the role approximately; check a complete phrase before approving.', '{"comparison":"Iyatuvosa is the complete sentence; matavosa is one organized phrase that can form part of it.","grammarFunction":"sentence built from interacting phrases","grammarGroup":"Building blocks","grammarExample":"E lako mai o Mere.","tables":[{"title":"Iyatuvosa · whole-sentence review order","columns":["Stage","Check","Do not assume"],"rows":[["1","Choose the sentence type and intended meaning","every sentence contains a vu"],["2","Bracket isema, matavu and matanauni where present","an English word boundary is a Fijian phrase boundary"],["3","Review the ordered roles inside each matavu","the same form has one permanent role"],["4","Review mata, yavu, modifiers and taukeni inside each matanauni","an English possessive or adjective supplies the Fijian marker"],["5","Check how the phrases relate and where they occur in an attested sentence","one fixed whole-sentence order covers every construction"]],"note":"In E lako mai o Mere, the named-person phrase o Mere follows the predicate phrase. Internal matavu order and the placement of a specifying matanauni are distinct checks."}],"quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"Fijian grammar term from the supplied visual guide. English labels explain the role approximately; check a complete phrase before approving."}}', '[{"sourceId":"534756bd7910","page":1}]', '[]', 'iyatuvosa | sentence built from interacting phrases | | an iyatuvosa is a whole sentence built from interacting phrases. first decide whether its construction is predicate-based, nominal, or another attested type. in a predicate sentence, check the internal matavu order, then identify any matanauni that specifies a participant outside that narrower phrase. its position in the whole sentence needs an attested example; one english word order or one fijian example is not a universal template.', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('929553b2e9266964', 'standard-fijian', 'grammar-term', 'iyatuvosa matanauni', 'iyatuvosa-matanauni', '', 'nominal sentence without an overt verb', '', 'An iyatuvosa matanauni is a complete sentence formed from two nominal phrases without a matavu in this teaching analysis. Examples pair o yau with na vunivai and nikua with na soqo. Bracket each nominal phrase and test their relationship; do not add an English-style is automatically.', '', 'Fijian grammar term from the supplied visual guide. English labels explain the role approximately; check a complete phrase before approving.', '{"comparison":"This sentence pattern is built around a matanauni; a predicate sentence contains a matavu. Do not insert a vu merely because English uses ''is''.","grammarFunction":"nominal sentence without an overt verb","grammarGroup":"Word building and roles","grammarExample":"O yau na vunivai. / Nikua na soqo.","quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"Fijian grammar term from the supplied visual guide. English labels explain the role approximately; check a complete phrase before approving."}}', '[{"sourceId":"534756bd7910","page":4},{"sourceId":"tuvavosa-matanauni-set-01-photos-2026-10-31","section":"3.3.6; P11"}]', '[]', 'iyatuvosa matanauni | nominal sentence without an overt verb | | an iyatuvosa matanauni is a complete sentence formed from two nominal phrases without a matavu in this teaching analysis. examples pair o yau with na vunivai and nikua with na soqo. bracket each nominal phrase and test their relationship; do not add an english-style is automatically.', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('5345126c7dee4ae3', 'standard-fijian', 'grammar-term', 'kilanauni', 'kilanauni', '', 'kn: a word or base that qualifies a nominal base inside a matanauni, such as levu in na vale levu.', '', 'A kilanauni adds information after the nominal base. In na kali vesi levu qori, vesi gives the kind or material, levu gives size, and qori points out which one. These are knn, knv, and knd in that order; a qualifying clause is another possible type.', '', 'Fijian grammar term from the supplied visual guide. English labels explain the role approximately; check a complete phrase before approving. The photographed section 3.4.3 supplies the Tuvavosa subtypes and order; independent noun-phrase research corroborates post-head qualification. The exact role of a new example still requires phrase review.', '{"comparison":"Kilanauni qualifies a nominal base inside a matanauni, as levu does in na vale levu. Kilavu qualifies a predicate base inside a matavu.","grammarCode":"kn","grammarFunction":"a word or base that qualifies a nominal base inside a matanauni, such as levu in na vale levu.","grammarGroup":"Noun phrase","grammarExample":"Na kali vesi levu qori.","marker":{"kind":"Duru qualifier","forms":"vesi · levu · qori (contextual examples)","position":"After the nominal yavu inside a matanauni.","note":"A qualifier narrows the nominal meaning; knn, knv, and knd name its different kinds."},"furtherLink":{"label":"Explore kilanauni in Sangam Education Board - Year 13 Kilanauni worksheet","href":"https://sangamedu.ac.fj/wp-content/uploads/2021/08/Vosa-Vakaviti-Worksheet-10.pdf"},"quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"Fijian grammar term from the supplied visual guide. English labels explain the role approximately; check a complete phrase before approving. The photographed section 3.4.3 supplies the Tuvavosa subtypes and order; independent noun-phrase research corroborates post-head qualification. The exact role of a new example still requires phrase review."}}', '[{"sourceId":"tuvavosa-review-scan-2026-10-30","section":"3.4.3"},{"sourceId":"sangam-kilanauni-worksheet-2021"},{"sourceId":"534756bd7910","page":2},{"sourceId":"anu-fijian-np-qualifiers-2026-11-03"}]', '[]', 'kilanauni | kn: a word or base that qualifies a nominal base inside a matanauni, such as levu in na vale levu. | | a kilanauni adds information after the nominal base. in na kali vesi levu qori, vesi gives the kind or material, levu gives size, and qori points out which one. these are knn, knv, and knd in that order; a qualifying clause is another possible type.', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('748106ea22352f25', 'standard-fijian', 'grammar-term', 'kilavu', 'kilavu', '', 'kv: a word or base that qualifies a predicate inside a matavu, such as vinaka in Oni bula vinaka sara.', '', 'A yavu that adds to or narrows the meaning of a vu inside a matavu. A kilavu may be nauni-based or vu-based. It is a Fijian phrase role, not a direct match for every English adverb.', '', 'Check this meaning and its use in a complete Fijian phrase before approving it.', '{"comparison":"Kilavu qualifies a predicate base inside a matavu, as vinaka does in Oni bula vinaka sara. Kilanauni qualifies a nominal base inside a matanauni.","grammarCode":"kv","grammarFunction":"a word or base that qualifies a predicate inside a matavu, such as vinaka in Oni bula vinaka sara.","grammarGroup":"Predicate phrase","grammarExample":"Oni bula vinaka sara. Here vinaka is kilavu vu; sara is durumuri in the scanned analysis.","marker":{"kind":"Duru qualifier","forms":"vinaka · yaqona (contextual examples)","position":"After the predicate yavu inside a matavu.","note":"A kilavu qualifies the predicate; kvn and kvv distinguish the base it uses."},"appsSite":{"englishChecked":false,"status":"needs review","notes":"The kilavu vu example was checked against the supplied TIFF scan (page 39, printed page 4-20). English explanation remains open to team review."}}', '[{"sourceId":"534756bd7910","page":3},{"sourceId":"tuvavosa-review-scan-2026-10-30","section":"4.5.2–4.5.3"}]', '[]', 'kilavu | kv: a word or base that qualifies a predicate inside a matavu, such as vinaka in oni bula vinaka sara. | | a yavu that adds to or narrows the meaning of a vu inside a matavu. a kilavu may be nauni-based or vu-based. it is a fijian phrase role, not a direct match for every english adverb.', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('c2a1e58ea1c20d20', 'standard-fijian', 'grammar-term', 'mata', 'mata', '', 'The introductory marker of a matanauni, such as na in na vale or vei in vei koya.', '', 'A duruliu that introduces a matanauni. Examples include na, o, i and vei; it is not simply the English article the.', '', 'Fijian grammar term from the supplied visual guide. English labels explain the role approximately; check a complete phrase before approving.', '{"comparison":"Mata introduces the noun phrase. Yavu is its meaning-bearing base; in na vale, na is the mata and vale is the base.","grammarFunction":"The introductory marker of a matanauni, such as na in na vale or vei in vei koya.","grammarGroup":"Noun phrase","grammarExample":"Sa moce o koya.","marker":{"kind":"Mata","forms":"na · o · vei · kei · i · e · mai · ni · me · se · de","position":"At the opening of a matanauni, according to its type.","note":"These are alternatives for different constructions, not a sequence to place together."},"quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"Fijian grammar term from the supplied visual guide. English labels explain the role approximately; check a complete phrase before approving."}}', '[{"sourceId":"534756bd7910","page":2}]', '[]', 'mata | the introductory marker of a matanauni, such as na in na vale or vei in vei koya. | | a duruliu that introduces a matanauni. examples include na, o, i and vei; it is not simply the english article the.', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('b8bbcb8b500c5429', 'standard-fijian', 'grammar-term', 'matanauni', 'matanauni', '', 'A phrase used to refer to a person, thing, place, time, or idea, such as na vale or vei koya.', '', 'A matanauni is a nominal phrase. Identify its subtype first. A matanauni raraba contains na as a mata; a matanauni toka does not. Within a counted common phrase, a quantity marker and wiliwili can precede the noun marker and yavu. Qualifiers follow their base in the knn → knv → knd sequence when all three occur. Taukeni uses a separate relationship-specific pattern.', '', 'Fijian grammar term from the supplied visual guide. English labels explain the role approximately; check a complete phrase before approving.', '{"comparison":"A matanauni names or points to a participant, place, time, or idea. A matavu expresses a predicate or event. Both are kinds of matavosa.","grammarFunction":"A phrase used to refer to a person, thing, place, time, or idea, such as na vale or vei koya.","grammarGroup":"Building blocks","grammarExample":"E rua na toa. / Na kali vesi levu qori.","tables":[{"title":"Matanauni · broad phrase review order","columns":["Stage","Role","Example or condition"],"rows":[["1","matanauni subtype","MNR with na, or an MNT subtype without na"],["2","outer mata, when present","e, i, mai or kei in an attested construction"],["3","mata ni wiliwili + wiliwili, when present","e rua or na dua; check both roles"],["4","mata + yavu","na + a common nominal base for MNR"],["5","kilanauni, when present","knn → knv → knd in this three-part pattern"],["6","taukeni, when present","choose the owner relationship and its own marker pattern"]],"note":"This is a review path, not a universal template. MNT subtypes have their own mata; quantity and taukeni can change the detailed construction."}],"quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"Fijian grammar term from the supplied visual guide. English labels explain the role approximately; check a complete phrase before approving."}}', '[{"sourceId":"534756bd7910","page":1}]', '[]', 'matanauni | a phrase used to refer to a person, thing, place, time, or idea, such as na vale or vei koya. | | a matanauni is a nominal phrase. identify its subtype first. a matanauni raraba contains na as a mata; a matanauni toka does not. within a counted common phrase, a quantity marker and wiliwili can precede the noun marker and yavu. qualifiers follow their base in the knn → knv → knd sequence when all three occur. taukeni uses a separate relationship-specific pattern.', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('cdf7d01c634a9968', 'standard-fijian', 'grammar-term', 'matanauni dusi', 'matanauni-dusi', '', 'MND: a pointing form used as the whole nominal phrase, such as oqo, qori, or oya.', '', 'Forms such as oqo/qo, oqori/qori and oya/ya can stand as the whole pointing phrase. They distinguish what is near the speaker, near the listener or farther from both. English demonstrative pronoun is an approximation for some uses; distinguish this phrase role from a kilanauni dusi qualifying a noun.', '', 'Fijian grammar term from the supplied visual guide. English labels explain the role approximately; check a complete phrase before approving. The photographed section 3.3.2 and the independent learning exercise both support the whole-phrase role. Shorter pointing forms may have a different role after a noun; do not merge them automatically.', '{"comparison":"This is the whole pointing phrase, such as oqo. Kilanauni dusi is a pointing form that qualifies a separate nominal base, as qo does in na siga qo.","grammarCode":"MND","grammarFunction":"Pointing phrase used on its own","grammarGroup":"Noun phrase","grammarExample":"Kauta mai oqori.","marker":{"kind":"Mata","forms":"none","position":"The pointing word itself stands as the nominal phrase.","note":"Oqo is a whole MND; qo after a noun can instead be a kilanauni dusi."},"furtherLink":{"label":"Explore matanauni dusi in Year 12 Nanuma Lesu Na Noda Vosa 12 - MND and MNYt exercises","href":"https://fliphtml5.com/gjgbb/jecb/Year_12_Nanuma_Lesu_Na_Noda_Vosa_12/#page=22"},"quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"Fijian grammar term from the supplied visual guide. English labels explain the role approximately; check a complete phrase before approving. The photographed section 3.3.2 and the independent learning exercise both support the whole-phrase role. Shorter pointing forms may have a different role after a noun; do not merge them automatically."}}', '[{"sourceId":"tuvavosa-review-scan-2026-10-30","section":"3.3.2"},{"sourceId":"nanuma-lesu-12-online-mnd-mnyt","page":22},{"sourceId":"534756bd7910","page":2}]', '[]', 'matanauni dusi | mnd: a pointing form used as the whole nominal phrase, such as oqo, qori, or oya. | | forms such as oqo/qo, oqori/qori and oya/ya can stand as the whole pointing phrase. they distinguish what is near the speaker, near the listener or farther from both. english demonstrative pronoun is an approximation for some uses; distinguish this phrase role from a kilanauni dusi qualifying a noun.', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('d05e02359d51ed48', 'standard-fijian', 'grammar-term', 'matanauni gauna', 'matanauni-gauna', '', 'MNG: a time expression used as a whole nominal phrase, such as nikua or nimataka.', '', 'A matanauni gauna (MNG) is a whole time expression without a separately functioning mata here. Enanoa/nanoa, edaidai, nikua and nimataka are examples. Do not split enanoa into e + na + noa just because it begins with those letters; compare e na yakavi, which is a matanauni raraba with a real na marker.', '', 'This explanation and its use in a complete Fijian phrase need team review.', '{"comparison":"This nominal expression points to a time, such as nikua. Matanauni vanua points to a place or direction, such as e ke or i tuba.","grammarCode":"MNG","grammarFunction":"Time phrase used on its own","grammarGroup":"Noun phrase","grammarExample":"Enanoa. / E na yakavi.","marker":{"kind":"Mata","forms":"none","position":"The time expression itself stands as the nominal phrase, as nikua does.","note":"Do not split a whole time word into an invented mata plus yavu."},"quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"Scan based learning explanation. OCR wording and Fijian terminology need team review before approval."}}', '[{"sourceId":"tuvavosa-review-scan-2026-10-30","section":"3.3.1"},{"sourceId":"534756bd7910","page":2},{"sourceId":"tuvavosa-matanauni-set-01-photos-2026-10-31","section":"3.3.1; P14"}]', '[]', 'matanauni gauna | mng: a time expression used as a whole nominal phrase, such as nikua or nimataka. | | a matanauni gauna (mng) is a whole time expression without a separately functioning mata here. enanoa/nanoa, edaidai, nikua and nimataka are examples. do not split enanoa into e + na + noa just because it begins with those letters; compare e na yakavi, which is a matanauni raraba with a real na marker.', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('5c4d1463e11cc848', 'standard-fijian', 'grammar-term', 'matanauni raraba', 'matanauni-raraba', '', 'MNR: a nominal phrase containing na, such as na vale or e na marau.', '', 'The marker na is present. A preceding mata may be e, i, mai or kei; when two mata occur, na comes after the first. In e na motoka, e and na are both mata. Identify the whole phrase in context.', '', 'This explanation and its use in a complete Fijian phrase need team review.', '{"role":{"fijian":"matanauni raraba","english":"nominal phrase with na"},"usageExamples":[{"fijian":"Era lade e na marau.","english":"They leap for joy.","words":[{"text":"Era","role":"durusau","english":"actor marker"},{"text":"lade","role":"vu","english":"predicate base"},{"text":"e na marau","role":"matanauni raraba","english":"nominal phrase with na","focus":true}],"punctuation":"."}],"comparison":"MNR and MNT are both nominal phrases. MNR contains na; MNT does not. Compare na vale with kei Jone or vei koya, then check each whole phrase in context.","grammarCode":"MNR","grammarFunction":"Nominal phrase with na","grammarGroup":"Noun phrase","grammarExample":"Na kali vesi levu qori.","marker":{"kind":"Mata","forms":"na","position":"Before the nominal yavu, including in a longer phrase such as e na marau.","note":"The presence of na distinguishes MNR from MNT."},"exploration":{"title":"Look for na","question":"Why does na vale belong here while kei Jone belongs with matanauni toka?"},"quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"Scan based learning explanation. OCR wording and Fijian terminology need team review before approval."}}', '[{"sourceId":"tuvavosa-review-scan-2026-10-30","section":"3.2.3"},{"sourceId":"534756bd7910","page":2}]', '[]', 'matanauni raraba | mnr: a nominal phrase containing na, such as na vale or e na marau. | | the marker na is present. a preceding mata may be e, i, mai or kei; when two mata occur, na comes after the first. in e na motoka, e and na are both mata. identify the whole phrase in context.', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('2a78f6166ad89481', 'standard-fijian', 'grammar-term', 'matanauni toka', 'matanauni-toka', '', 'MNT: a nominal phrase without na, such as kei Jone or vei koya.', '', 'This phrase family ordinarily has one mata and contains matanauni yaca (MNY), sosomi (MNS), yacanivanua (MNYV) and vanua (MNV). The marker and base in the actual phrase determine the subtype.', '', 'This explanation and its use in a complete Fijian phrase need team review.', '{"role":{"fijian":"matanauni toka / matanauni yaca","english":"proper-name phrase without na"},"usageExamples":[{"fijian":"Drau cici kei Jone.","english":"You two run with Jone.","words":[{"text":"Drau","role":"durusau","english":"actor marker for two people"},{"text":"cici","role":"vu","english":"predicate base"},{"text":"kei Jone","role":"matanauni toka / matanauni yaca","english":"proper-name phrase without na","focus":true}],"punctuation":"."}],"comparison":"MNT and MNR are both nominal phrases. MNT has no na; MNR contains na. Name, pronoun, and place phrases are common MNT types, but classify the whole phrase.","grammarCode":"MNT","grammarFunction":"Nominal phrase without na","grammarGroup":"Noun phrase","marker":{"kind":"Mata","forms":"o · vei · kei · i · e · mai (by subtype)","position":"Before a personal name, pronoun, place name, or location where that subtype requires one.","note":"MNT does not use na as its nominal marker; check the subtype for the actual mata."},"exploration":{"title":"A phrase without na","question":"What changes when the phrase names Jone rather than a common noun such as vale?"},"quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"Scan based learning explanation. OCR wording and Fijian terminology need team review before approval."}}', '[{"sourceId":"tuvavosa-review-scan-2026-10-30","section":"3.2.4"},{"sourceId":"534756bd7910","page":2}]', '[]', 'matanauni toka | mnt: a nominal phrase without na, such as kei jone or vei koya. | | this phrase family ordinarily has one mata and contains matanauni yaca (mny), sosomi (mns), yacanivanua (mnyv) and vanua (mnv). the marker and base in the actual phrase determine the subtype.', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('efb62399bee7ac53', 'standard-fijian', 'grammar-term', 'matanauni yatuvosa', 'matanauni-yatuvosa', '', 'MNYt: a whole clause used where a nominal phrase can stand, often introduced by ni, me, se, or de.', '', 'A matanauni yatuvosa (MNYt) is a whole clause serving a nominal-phrase role. In this pattern, ni, me, se or de can introduce it after a suitable predicate of thinking, speech or inquiry. Bracket the entire clause before labeling its internal words. This differs from kilanauni yatuvosa, where a clause qualifies an existing nominal base.', '', 'Fijian grammar term from the supplied visual guide. English labels explain the role approximately; check a complete phrase before approving.', '{"comparison":"A whole clause fills a nominal phrase position. Kilanauni yatuvosa is a clause that qualifies a separate noun instead.","grammarCode":"MNYt","grammarFunction":"Clause used where a nominal phrase can stand","grammarGroup":"Noun phrase","grammarExample":"Au kaya de o sā lako.","marker":{"kind":"Mata","forms":"ni · me · se · de","position":"Before the clause used as a nominal phrase, when the construction calls for one.","note":"The entire introduced clause fills a nominal position."},"furtherLink":{"label":"Explore matanauni yatuvosa in Year 12 Nanuma Lesu Na Noda Vosa 12 - MND and MNYt exercises","href":"https://fliphtml5.com/gjgbb/jecb/Year_12_Nanuma_Lesu_Na_Noda_Vosa_12/#page=32"},"quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"Fijian grammar term from the supplied visual guide. English labels explain the role approximately; check a complete phrase before approving."}}', '[{"sourceId":"tuvavosa-review-scan-2026-10-30","section":"3.3.3"},{"sourceId":"nanuma-lesu-12-online-mnd-mnyt","page":32},{"sourceId":"534756bd7910","page":2},{"sourceId":"tuvavosa-matanauni-set-01-photos-2026-10-31","section":"3.3.3; P13–P12"}]', '[]', 'matanauni yatuvosa | mnyt: a whole clause used where a nominal phrase can stand, often introduced by ni, me, se, or de. | | a matanauni yatuvosa (mnyt) is a whole clause serving a nominal-phrase role. in this pattern, ni, me, se or de can introduce it after a suitable predicate of thinking, speech or inquiry. bracket the entire clause before labeling its internal words. this differs from kilanauni yatuvosa, where a clause qualifies an existing nominal base.', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('a9f4dacb90507486', 'standard-fijian', 'grammar-term', 'matavosa', 'matavosa', '', 'A phrase organized around a meaning-bearing yavu, with any duru that accompany it; matanauni and matavu are its two main kinds.', '', 'The guide names matanauni and matavu as two major kinds of matavosa.', '', 'Fijian grammar term from the supplied visual guide. English labels explain the role approximately; check a complete phrase before approving. The photographed Tuvavosa explanation describes yavu and duru; independent school exercises use matavosa for both a nominal phrase and a predicate phrase. The role of any new phrase still needs checking.', '{"comparison":"Matavosa is the wider phrase category. Matanauni is its nominal kind; matavu is its predicate kind. Each has a yavu and may have accompanying duru.","grammarFunction":"A phrase organized around a meaning-bearing yavu, with any duru that accompany it; matanauni and matavu are its two main kinds.","grammarGroup":"Building blocks","furtherLink":{"label":"Explore matavosa in Nanuma Lesu Na Noda Vosa 13 - Tuvavosa exercises, page 87","href":"https://fliphtml5.com/gjgbb/elah/Year_13_Nanuma_Lesu_Na_Noda_Vosa_13/87/"},"quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"Fijian grammar term from the supplied visual guide. English labels explain the role approximately; check a complete phrase before approving. The photographed Tuvavosa explanation describes yavu and duru; independent school exercises use matavosa for both a nominal phrase and a predicate phrase. The role of any new phrase still needs checking."}}', '[{"sourceId":"534756bd7910","page":1},{"sourceId":"nanuma-lesu-year13-durugauna"},{"sourceId":"sangam-kilanauni-worksheet-2021"}]', '[]', 'matavosa | a phrase organized around a meaning-bearing yavu, with any duru that accompany it; matanauni and matavu are its two main kinds. | | the guide names matanauni and matavu as two major kinds of matavosa.', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('c2f6c313fbc741ca', 'standard-fijian', 'grammar-term', 'matavu', 'matavu', '', 'A phrase expressing an action, state, or other predicate, such as Au sa lako yani; it has a yavu and may have duru.', '', 'A matavu is a predicate phrase. Its broad teaching order is isema, durusau, durugauna and other duruliu, a yavu with any permitted additions, then an eligible nauni qali, kilavu, durumuri, and eligible kilavu tale. These are ordered positions, not a list of required words. Check each word''s actual construction and meaning before assigning a role.', '', 'This explanation and its use in a complete Fijian phrase need team review.', '{"comparison":"A matavu expresses what happens or is said about someone or something. A matanauni names or points to a participant, place, time, or idea.","grammarFunction":"A phrase expressing an action, state, or other predicate, such as Au sa lako yani; it has a yavu and may have duru.","grammarGroup":"Building blocks","grammarExample":"Oni bula vinaka sara.","tables":[{"title":"Matavu · sentence review order","columns":["Stage","Tuvavosa role","Use only when"],"rows":[["1","isema","the clause needs a connector; one or two in the pattern''s order"],["2","durusau","person and number match the intended sau; may be unspoken"],["3","durugauna and other duruliu","their source-specific order and meaning fit"],["4","ikuri – yavu – ikuri","the actual base licenses each attached form"],["5","nauni qali (nq)","a suitable dewa form takes this phrase type"],["6","kilavu (kv)","the qualifier narrows this predicate"],["7","durumuri (dm)","the following form and its internal order fit"],["8","kilavu tale","the particular qualifier permits this later slot"]],"note":"The compact sequence is dl · k–y–k · nq · kv · dm · kv. Optional stages may be absent; classify an entire phrase first."}],"furtherLink":{"label":"Explore matavu in ANU: Surface order in the Standard Fijian verb phrase","href":"https://openresearch-repository.anu.edu.au/bitstreams/86dd578b-ce08-4a6a-902b-302e765e5286/download"},"quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"Tuvavosa teaching explanation checked against the supplied printed scan and independent research. Phrase wording and contextual role still need team review."}}', '[{"sourceId":"tuvavosa-review-scan-2026-10-30","page":24,"section":"4.1.1"},{"sourceId":"anu-fijian-verb-phrase-surface-order"}]', '[]', 'matavu | a phrase expressing an action, state, or other predicate, such as au sa lako yani; it has a yavu and may have duru. | | a matavu is a predicate phrase. its broad teaching order is isema, durusau, durugauna and other duruliu, a yavu with any permitted additions, then an eligible nauni qali, kilavu, durumuri, and eligible kilavu tale. these are ordered positions, not a list of required words. check each word''s actual construction and meaning before assigning a role.', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('2a907d22b0e1329d', 'standard-fijian', 'grammar-term', 'nauni', 'nauni', '', 'A noun-like base that can carry the main meaning of a matanauni, such as vale in na vale.', '', 'A yavu that ordinarily forms the centre of a matanauni; the label describes usual function in a phrase.', '', 'Fijian grammar term from the supplied visual guide. English labels explain the role approximately; check a complete phrase before approving.', '{"comparison":"Nauni names the lexical base. Matanauni is the whole phrase, which may also include a mata and qualifiers.","grammarFunction":"A noun-like base that can carry the main meaning of a matanauni, such as vale in na vale.","grammarGroup":"Noun phrase","grammarExample":"Sa bale na vesi.","quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"Fijian grammar term from the supplied visual guide. English labels explain the role approximately; check a complete phrase before approving."}}', '[{"sourceId":"534756bd7910","page":2}]', '[]', 'nauni | a noun-like base that can carry the main meaning of a matanauni, such as vale in na vale. | | a yavu that ordinarily forms the centre of a matanauni; the label describes usual function in a phrase.', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('f81bd0fff20597ba', 'standard-fijian', 'grammar-term', 'nauni qali', 'nauni-qali', '', 'named or pronominal object within a predicate phrase', '', 'In Standard Fijian, a pronoun, personal name or place name may follow a suitable -i dewa form immediately within the matavu. A common noun phrase such as na gone stands outside that narrower nq slot. Lau usage may differ.', '', 'This explanation and its use in a complete Fijian phrase need team review.', '{"comparison":"Nauni qali names an object expression within a matavu; qali names the affected-participant relationship. The expression and the semantic role are not the same label.","grammarCode":"nq","grammarFunction":"named or pronominal object within a predicate phrase","grammarGroup":"Predicate phrase","grammarExample":"Au raici Jo tiko. / Au raica tiko na gone.","tables":[{"title":"Nauni qali and a common noun phrase","columns":["Phrase","Analysis","Boundary"],"rows":[["au raici Jo tiko","Jo = nauni qali (nq)","within matavu after raici"],["au raica tiko na gone","na gone = matanauni raraba","follows the matavu"]],"note":"Check the variety and the whole sentence before assigning this role."}],"furtherLink":{"label":"Explore nauni qali in ANU: Surface order in the Standard Fijian verb phrase","href":"https://openresearch-repository.anu.edu.au/bitstreams/86dd578b-ce08-4a6a-902b-302e765e5286/download"},"quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"Tuvavosa teaching explanation checked against the supplied printed scan and independent research. Phrase wording and contextual role still need team review."}}', '[{"sourceId":"tuvavosa-review-scan-2026-10-30","page":24,"section":"4.1.1; 4.5.1"},{"sourceId":"anu-fijian-verb-phrase-surface-order"},{"sourceId":"tuvavosa-4-4-4-5-photos-2026-10-31","section":"4.5.1"}]', '[]', 'nauni qali | named or pronominal object within a predicate phrase | | in standard fijian, a pronoun, personal name or place name may follow a suitable -i dewa form immediately within the matavu. a common noun phrase such as na gone stands outside that narrower nq slot. lau usage may differ.', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('5df4230563a56628', 'standard-fijian', 'grammar-term', 'nauni sosomi', 'nauni-sosomi', '', 'An independent pronoun that can be the nominal base of a phrase, such as yau in o yau.', '', 'Nauni sosomi are independent nominal pronoun forms. The table groups them by person and number, including whether ''we'' includes the listener. A form used as durusau in a predicate has a different phrase role.', '', 'Check person, number, inclusion, spelling and phrase role before approving these forms.', '{"comparison":"Nauni sosomi is an independent pronoun form, such as koya. Matanauni sosomi (MNS) is the whole phrase, such as vei koya, including its marker.","grammarFunction":"An independent pronoun that can be the nominal base of a phrase, such as yau in o yau.","grammarGroup":"Noun phrase","grammarExample":"Na tagane mamakutu o koya.","tables":[{"title":"Nauni sosomi · independent pronouns","columns":["Wiliwili · number","Tamata qo · speaker, excluding listener","Tamata qori · listener","Tamata ya · third person","Tamata okati · speaker and listener"],"rows":[["Le dua · one","yau","iko","koya","—"],["Le rua · two","keirau","kemudrau","rau","kedaru"],["Le vica · a few","keitou","kemudou","iratou","kedatou"],["Le levu · many","keimami","kemuni","ira","keda"]],"note":"The inclusive group has no singular form. These are independent pronoun forms; the role of a form in a sentence still needs phrase evidence. The variant ‘raout’ needs speaker review."}],"exploration":{"title":"One word inside a larger phrase","question":"In vei koya, what does koya contribute that vei alone cannot?"},"furtherLink":{"label":"Explore nauni sosomi in ANU thesis: Standard Fijian pronoun paradigm (Table 7.2)","href":"https://openresearch-repository.anu.edu.au/bitstreams/ad8ffd53-3125-4166-885e-a761ec8bf989/download"},"quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"Person and number table transcribed from the supplied scan and checked against an independent pronoun paradigm. The user typed ''raout''; the scanned form is ''iratou''. Team review remains required. The photographed pronoun chart and the independent Fijian pronoun paradigm agree on person, number and listener inclusion. An independent pronoun can take different sentence roles in context."}}', '[{"sourceId":"534756bd7910","page":2},{"sourceId":"tuvavosa-review-scan-2026-10-30","section":"3.4.4"},{"sourceId":"fijian-pronoun-paradigm-study"}]', '[]', 'nauni sosomi | an independent pronoun that can be the nominal base of a phrase, such as yau in o yau. | | nauni sosomi are independent nominal pronoun forms. the table groups them by person and number, including whether ''we'' includes the listener. a form used as durusau in a predicate has a different phrase role.', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('489e3c0f662e174a', 'standard-fijian', 'grammar-term', 'qali', 'qali', '', 'object or affected participant as a semantic role', '', 'The participant or thing toward which an event is directed or that is affected by it.', '', 'Fijian grammar term from the supplied visual guide. English labels explain the role approximately; check a complete phrase before approving.', '{"comparison":"Qali is the affected participant; sau is the actor. Nauni qali is an expression occupying an object position in a matavu.","grammarFunction":"object or affected participant as a semantic role","grammarGroup":"Word building and roles","grammarExample":"Au raica na gone.","appsSite":{"englishChecked":false,"status":"needs review","notes":"Fijian grammar term from the supplied visual guide. English labels explain the role approximately; check a complete phrase before approving."}}', '[{"sourceId":"534756bd7910","page":4}]', '[]', 'qali | object or affected participant as a semantic role | | the participant or thing toward which an event is directed or that is affected by it.', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('83fdf17478ce3341', 'standard-fijian', 'grammar-term', 'sau', 'sau', '', 'actor or agent as a semantic role', '', 'The participant who performs, starts or experiences an event, distinct from the affected participant or qali.', '', 'Fijian grammar term from the supplied visual guide. English labels explain the role approximately; check a complete phrase before approving.', '{"comparison":"Sau is the actor or subject participant; qali is the affected participant. Durusau points to the sau within a matavu.","grammarFunction":"actor or agent as a semantic role","grammarGroup":"Word building and roles","grammarExample":"Au raica na gone.","appsSite":{"englishChecked":false,"status":"needs review","notes":"Fijian grammar term from the supplied visual guide. English labels explain the role approximately; check a complete phrase before approving."}}', '[{"sourceId":"534756bd7910","page":4}]', '[]', 'sau | actor or agent as a semantic role | | the participant who performs, starts or experiences an event, distinct from the affected participant or qali.', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('5c49a1f40218e9ed', 'standard-fijian', 'grammar-term', 'taukeni', 'taukeni', '', 'A relationship between a noun and a person or thing connected to it: owner, intended user, food or drink recipient, body part, or relative.', '', 'A relationship between the yavu of a matanauni and another person or thing. The related base may be a named person (NY), a common noun (NR), or a pronoun, and each uses a different pattern. It can mean ownership, maker or performer, intended recipient or topic, food or drink for someone, or a direct body-part/kinship relation. Choose the relation before translating English ''someone''s''.', '', 'This explanation and its use in a complete Fijian phrase need team review.', '{"comparison":"Different taukeni patterns use different markers. Nei may show ownership or maker; kei can show who something concerns or who will consume food; mei relates to drink; i can link body parts or kin.","grammarFunction":"A relationship between a noun and a person or thing connected to it: owner, intended user, food or drink recipient, body part, or relative.","grammarGroup":"Noun phrase","grammarExample":"Sa boro na vale nei Luke.","furtherLink":{"label":"Explore taukeni in QMUL GLOW 42: Fijian possessive classifiers as nominal Appl heads","href":"https://glowlinguistics.org/42/wp-content/uploads/sites/4/2019/03/GLOW_FJPoss.pdf"},"quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"Source-led Tuvavosa learning explanation. The supplied scan and independent analyses support the pattern; wording and sentence examples still need team review."}}', '[{"sourceId":"534756bd7910","page":2},{"sourceId":"tuvavosa-review-scan-2026-10-30","section":"3.5.1-3.5.4"},{"sourceId":"qmul-fijian-possession-2019"}]', '[]', 'taukeni | a relationship between a noun and a person or thing connected to it: owner, intended user, food or drink recipient, body part, or relative. | | a relationship between the yavu of a matanauni and another person or thing. the related base may be a named person (ny), a common noun (nr), or a pronoun, and each uses a different pattern. it can mean ownership, maker or performer, intended recipient or topic, food or drink for someone, or a direct body-part/kinship relation. choose the relation before translating english ''someone''s''.', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('9124a72f07f45315', 'standard-fijian', 'grammar-term', 'tuvavosa', 'tuvavosa', '', 'Fijian grammar system for words, phrases, and sentences', '', 'The guide follows meaningful bases and supporting elements as they build phrases and sentences.', '', 'Fijian grammar term from the supplied visual guide. English labels explain the role approximately; check a complete phrase before approving.', '{"comparison":"English parts of speech label words; Tuvavosa also distinguishes word building and each form''s role in a matanauni, matavu, or iyatuvosa.","grammarFunction":"Fijian grammar system for words, phrases, and sentences","grammarGroup":"Building blocks","appsSite":{"englishChecked":false,"status":"needs review","notes":"Fijian grammar term from the supplied visual guide. English labels explain the role approximately; check a complete phrase before approving."}}', '[{"sourceId":"534756bd7910","page":1}]', '[]', 'tuvavosa | fijian grammar system for words, phrases, and sentences | | the guide follows meaningful bases and supporting elements as they build phrases and sentences.', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('de65c044a3897b9e', 'standard-fijian', 'grammar-term', 'vosa tuvai', 'vosa-tuvai', '', 'A Fijian word role used to build a matavosa, such as yavu, duru, kilanauni, or kilavu; the role depends on the phrase.', '', 'In this Tuvavosa framework, vosa tuvai are words arranged with other words to build a matavosa. A vosa tuvai may serve as a yavu or a duru. This is related to describing parts of speech in English, but the Fijian roles are not a one-to-one noun, verb and adjective list. Ikurau are treated separately as more independent expressions.', '', 'This explanation and its use in a complete Fijian phrase need team review.', '{"comparison":"Vosa tuvai is related to English parts of speech, but one Fijian word may act as a nominal base, predicate base, or qualifier in different constructions.","grammarFunction":"A Fijian word role used to build a matavosa, such as yavu, duru, kilanauni, or kilavu; the role depends on the phrase.","grammarGroup":"Building blocks","exploration":{"title":"A role appears in a phrase","question":"Could one Fijian word be a yavu in one phrase and a kilavu in another? Which phrases would show it?"},"quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"Scan based learning explanation. OCR wording and Fijian terminology need team review before approval."}}', '[{"sourceId":"tuvavosa-review-scan-2026-10-30","section":"3.1.2"},{"sourceId":"534756bd7910","page":1}]', '[]', 'vosa tuvai | a fijian word role used to build a matavosa, such as yavu, duru, kilanauni, or kilavu; the role depends on the phrase. | | in this tuvavosa framework, vosa tuvai are words arranged with other words to build a matavosa. a vosa tuvai may serve as a yavu or a duru. this is related to describing parts of speech in english, but the fijian roles are not a one-to-one noun, verb and adjective list. ikurau are treated separately as more independent expressions.', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('0b1f6706dff303df', 'standard-fijian', 'grammar-term', 'vu', 'vu', '', 'A predicate base inside a matavu, such as lako in Au sa lako yani.', '', 'The yavu normally heading a matavu; it may express a condition or quality as well as an action.', '', 'Fijian grammar term from the supplied visual guide. English labels explain the role approximately; check a complete phrase before approving.', '{"comparison":"Vu is the predicate base in a matavu. Yavu is the wider term for the meaning-bearing base of a phrase, including nominal bases.","grammarFunction":"A predicate base inside a matavu, such as lako in Au sa lako yani.","grammarGroup":"Predicate phrase","grammarExample":"Sa totoka sara o Sera.","quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"Fijian grammar term from the supplied visual guide. English labels explain the role approximately; check a complete phrase before approving."}}', '[{"sourceId":"534756bd7910","page":3}]', '[]', 'vu | a predicate base inside a matavu, such as lako in au sa lako yani. | | the yavu normally heading a matavu; it may express a condition or quality as well as an action.', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('b3085218f6189463', 'standard-fijian', 'grammar-term', 'wiliwili', 'wiliwili', '', 'w: number or quantity expression within a matanauni', '', 'Wiliwili (w) is a quantity expression that can modify a nominal base in a counted matanauni. E rua na gone shows mw–w–m–y. It includes numerals, vica, sō and levu/vūqa; vica can ask how many or refer to a few. A quantity form after a noun can belong to another construction and must be analyzed again.', '', 'Fijian grammar term from the supplied visual guide. English labels explain the role approximately; check a complete phrase before approving.', '{"comparison":"Wiliwili is the number or quantity expression; mata ni wiliwili is the marker immediately before it in a matanauni.","grammarFunction":"w: number or quantity expression within a matanauni","grammarGroup":"Noun phrase","grammarExample":"E rua na gone.","quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"Fijian grammar term from the supplied visual guide. English labels explain the role approximately; check a complete phrase before approving."}}', '[{"sourceId":"tuvavosa-review-scan-2026-10-30","section":"3.4.1"},{"sourceId":"534756bd7910","page":2},{"sourceId":"tuvavosa-matanauni-set-01-photos-2026-10-31","section":"3.4.1; P09"}]', '[]', 'wiliwili | w: number or quantity expression within a matanauni | | wiliwili (w) is a quantity expression that can modify a nominal base in a counted matanauni. e rua na gone shows mw–w–m–y. it includes numerals, vica, so and levu/vuqa; vica can ask how many or refer to a few. a quantity form after a noun can belong to another construction and must be analyzed again.', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('e6e3c90c7074c53a', 'standard-fijian', 'grammar-term', 'yavu', 'yavu', '', 'The meaning-bearing base of a phrase, such as vale in na vale or lako in Au sa lako; also a distinct word for a house site or foundation.', '', 'The element that carries the central lexical meaning of a phrase.', '', 'Fijian grammar term from the supplied visual guide. English labels explain the role approximately; check a complete phrase before approving. The photographed Tuvavosa explanation and an independent Year 10 worksheet both identify the base role. This grammatical sense remains separate from the physical house-site sense.', '{"comparison":"Yavu is the meaning-bearing base in a phrase. Vu is a predicate base; it is one possible yavu in a matavu, but not every yavu is a vu.","grammarFunction":"The meaning-bearing base of a phrase, such as vale in na vale or lako in Au sa lako; also a distinct word for a house site or foundation.","grammarGroup":"Building blocks","grammarExample":"qasi · vale · totoka","furtherLink":{"label":"Explore yavu in Sangam SKM College Nadi - Year 10 Vosa Vakaviti worksheet","href":"https://sangamedu.ac.fj/wp-content/uploads/2021/06/Vosa-VakaViti-Sheet-2-1.pdf"},"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"Fijian grammar term from the supplied visual guide. English labels explain the role approximately; check a complete phrase before approving. The photographed Tuvavosa explanation and an independent Year 10 worksheet both identify the base role. This grammatical sense remains separate from the physical house-site sense."}}', '[{"sourceId":"534756bd7910","page":1},{"sourceId":"sangam-year10-yavu-2021"}]', '[]', 'yavu | the meaning-bearing base of a phrase, such as vale in na vale or lako in au sa lako; also a distinct word for a house site or foundation. | | the element that carries the central lexical meaning of a phrase.', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('2a8920fe5d243d8f', 'standard-fijian', 'grammar-term', 'imasuti', 'imasuti', '', 'person addressed after an expressive form', '', 'This label describes the name or person addressed after an ikurau. The role belongs to the whole expression in context.', '', 'This explanation and its use in a complete Fijian phrase need team review.', '{"comparison":"Imasuti identifies the person addressed in an expressive construction; sau identifies an actor or subject. Address and actor are different roles.","grammarFunction":"person addressed after an expressive form","grammarGroup":"Building blocks","quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"Scan based learning explanation. OCR wording and Fijian terminology need team review before approval."}}', '[{"sourceId":"tuvavosa-review-scan-2026-10-30","section":"3.1.2"}]', '["family"]', 'imasuti | person addressed after an expressive form | | this label describes the name or person addressed after an ikurau. the role belongs to the whole expression in context.', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
