INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('939372887048486c', 'standard-fijian', 'grammar-term', 'semavosa', 'semavosa', '', 'study of how bases and additions join to form words', '', 'This looks at how a yavu combines with an ikuri. It concerns word formation within the broader study of Tuvavosa.', '', 'This explanation and its use in a complete Fijian phrase need team review.', '{"comparison":"Semavosa concerns how bases and additions form words; tuvavosa also describes how those words function in phrases and sentences.","grammarFunction":"study of how bases and additions join to form words","grammarGroup":"Word building and roles","quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"Scan based learning explanation. OCR wording and Fijian terminology need team review before approval."}}', '[{"sourceId":"tuvavosa-review-scan-2026-10-30","section":"3.1.1"}]', '[]', 'semavosa | study of how bases and additions join to form words | | this looks at how a yavu combines with an ikuri. it concerns word formation within the broader study of tuvavosa.', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('11945a725a1189e1', 'standard-fijian', 'grammar-term', 'matanauni yaca', 'matanauni-yaca', '', 'MNY: a phrase without na built around a personal name, as kei Jone is in Drau cici kei Jone.', '', 'The mata may be o, vei, kei or i. For example, kei Jone is a name phrase within a larger sentence. The name is the base; confirm the role from the complete phrase.', '', 'This explanation and its use in a complete Fijian phrase need team review.', '{"comparison":"Matanauni yaca names a person; matanauni sosomi uses a pronoun instead, as in vei koya. Both are forms of matanauni toka.","grammarCode":"MNY","grammarFunction":"Personal-name phrase without na","grammarGroup":"Noun phrase","grammarExample":"Drau cici kei Jone.","marker":{"kind":"Mata","forms":"o · vei · kei · i","position":"Before a personal name, such as kei Jone.","note":"The selected marker depends on the phrase’s role in its sentence."},"quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"Scan based learning explanation. OCR wording and Fijian terminology need team review before approval."}}', '[{"sourceId":"tuvavosa-review-scan-2026-10-30","section":"3.2.4"}]', '[]', 'matanauni yaca | mny: a phrase without na built around a personal name, as kei jone is in drau cici kei jone. | | the mata may be o, vei, kei or i. for example, kei jone is a name phrase within a larger sentence. the name is the base; confirm the role from the complete phrase.', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('d8a3be81dd5d0fba', 'standard-fijian', 'grammar-term', 'matanauni sosomi', 'matanauni-sosomi', '', 'MNS: a phrase with an independent pronoun and a marker such as o, vei, kei, or i; it does not use na.', '', 'The marker and pronoun together form this type of matanauni toka. The pronoun by itself is a nauni sosomi. A durusau inside a matavu has a different sentence role.', '', 'This explanation and its use in a complete Fijian phrase need team review.', '{"role":{"fijian":"matanauni sosomi","english":"pronoun-based phrase without na"},"usageExamples":[{"fijian":"Solia vei koya.","english":"Give it to him or her.","words":[{"text":"Solia","role":"vu","english":"predicate base"},{"text":"vei koya","role":"matanauni sosomi","english":"pronoun-based phrase without na","focus":true}],"punctuation":"."}],"comparison":"In Solia vei koya, vei koya is the whole matanauni sosomi (MNS); koya alone is the nauni sosomi (pronoun). Matanauni yaca uses a name, such as kei Jone.","grammarCode":"MNS","grammarFunction":"Pronoun-based phrase without na","grammarGroup":"Noun phrase","marker":{"kind":"Mata","forms":"o · vei · kei · i","position":"Before an independent pronoun, such as vei koya.","note":"The whole phrase is MNS; koya alone is the pronoun."},"exploration":{"title":"The whole pronoun phrase","question":"In vei koya, which part would change if you were speaking about a different person?"},"quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"Scan based learning explanation. OCR wording and Fijian terminology need team review before approval."}}', '[{"sourceId":"tuvavosa-review-scan-2026-10-30","section":"3.2.4"},{"sourceId":"naisema-user-practice-20261031"}]', '[]', 'matanauni sosomi | mns: a phrase with an independent pronoun and a marker such as o, vei, kei, or i; it does not use na. | | the marker and pronoun together form this type of matanauni toka. the pronoun by itself is a nauni sosomi. a durusau inside a matavu has a different sentence role.', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('6a8d0f4f91ce781e', 'standard-fijian', 'grammar-term', 'matanauni yacanivanua', 'matanauni-yacanivanua', '', 'MNYV: a phrase without na built around the name of a place, such as i Viti or mai Lautoka.', '', 'The mata may be o, kei, e, i or mai. The base can name a country, island, town or another named place; this category is broader than countries alone. Determine the marker''s role in the sentence.', '', 'This explanation and its use in a complete Fijian phrase need team review.', '{"comparison":"A named place such as Viti is MNYV in this phrase. A location word such as ke or tuba forms matanauni vanua instead.","grammarCode":"MNYV","grammarFunction":"Named-place phrase without na","grammarGroup":"Noun phrase","grammarExample":"i Viti · mai Lautoka","marker":{"kind":"Mata","forms":"o · kei · e · i · mai (by context)","position":"Before a named place, such as i Viti or mai Lautoka.","note":"Use the marker that fits the sentence’s place or direction relationship."},"quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"Scan based learning explanation. OCR wording and Fijian terminology need team review before approval."}}', '[{"sourceId":"tuvavosa-review-scan-2026-10-30","section":"3.2.4"}]', '[]', 'matanauni yacanivanua | mnyv: a phrase without na built around the name of a place, such as i viti or mai lautoka. | | the mata may be o, kei, e, i or mai. the base can name a country, island, town or another named place; this category is broader than countries alone. determine the marker''s role in the sentence.', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('3c45241b14f12b39', 'standard-fijian', 'grammar-term', 'matanauni vanua', 'matanauni-vanua', '', 'MNV: a phrase without na that tells where or in which direction, as e ke or i tuba does.', '', 'The mata may be e, i or mai. For example, e ke locates and i tuba points to a direction or place outside. Distinguish a location expression from a named place and analyze the full sentence.', '', 'This explanation and its use in a complete Fijian phrase need team review.', '{"comparison":"Matanauni vanua uses a location or direction expression; matanauni yacanivanua is built around a named place, such as i Viti.","grammarCode":"MNV","grammarFunction":"Location or direction phrase without na","grammarGroup":"Noun phrase","grammarExample":"e ke · i tuba","marker":{"kind":"Mata","forms":"e · i · mai","position":"Before a location or direction word, such as e ke or i tuba.","note":"A named place is classified separately as MNYV."},"quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"Scan based learning explanation. OCR wording and Fijian terminology need team review before approval."}}', '[{"sourceId":"tuvavosa-review-scan-2026-10-30","section":"3.2.4"}]', '[]', 'matanauni vanua | mnv: a phrase without na that tells where or in which direction, as e ke or i tuba does. | | the mata may be e, i or mai. for example, e ke locates and i tuba points to a direction or place outside. distinguish a location expression from a named place and analyze the full sentence.', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('567395862712c297', 'standard-fijian', 'grammar-term', 'matanauni sema', 'matanauni-sema', '', 'linked nominal phrases sharing one sentence role', '', 'Matanauni sema joins two or more nominal phrases sharing one sentence role. Sosoqoni groups distinct referents and may use kei, se or no spoken link in these constructions. Veitokoni places phrases that identify the same referent together without that link in these examples. Decide whether the referents are distinct before choosing a linker.', '', 'This explanation and its use in a complete Fijian phrase need team review.', '{"comparison":"Matanauni sema links nominal phrases that share a sentence role; isema links clauses or matavu. Check what units are joined.","grammarFunction":"linked nominal phrases sharing one sentence role","grammarGroup":"Noun phrase","grammarExample":"Na turaga na rātū. / Na sabutu kei na ogo.","quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"Scan based learning explanation. OCR wording and Fijian terminology need team review before approval."}}', '[{"sourceId":"tuvavosa-review-scan-2026-10-30","section":"3.3.5"},{"sourceId":"tuvavosa-matanauni-set-01-photos-2026-10-31","section":"3.3.5; P11"}]', '[]', 'matanauni sema | linked nominal phrases sharing one sentence role | | matanauni sema joins two or more nominal phrases sharing one sentence role. sosoqoni groups distinct referents and may use kei, se or no spoken link in these constructions. veitokoni places phrases that identify the same referent together without that link in these examples. decide whether the referents are distinct before choosing a linker.', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('c33a647103297884', 'standard-fijian', 'grammar-term', 'sosoqoni', 'sosoqoni', '', 'Different people or things joined into one sentence role, with kei, se, or no spoken linker.', '', 'A type of matanauni sema: two or more distinct referents are grouped in one sentence role. The linking mata can be kei or se, or there may be no spoken linker. Do not insert an English-style and automatically.', '', 'This explanation and its use in a complete Fijian phrase need team review.', '{"comparison":"In sosoqoni, the joined phrases refer to different things, as na dalo kei na uvi does. In veitokoni, adjacent phrases identify the same person or thing.","grammarFunction":"Different people or things joined into one sentence role, with kei, se, or no spoken linker.","grammarGroup":"Noun phrase","grammarExample":"na dalo kei na uvi","quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"Scan based learning explanation. OCR wording and Fijian terminology need team review before approval."}}', '[{"sourceId":"tuvavosa-review-scan-2026-10-30","section":"3.3.5"}]', '[]', 'sosoqoni | different people or things joined into one sentence role, with kei, se, or no spoken linker. | | a type of matanauni sema: two or more distinct referents are grouped in one sentence role. the linking mata can be kei or se, or there may be no spoken linker. do not insert an english-style and automatically.', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('bc1eb5568449a94c', 'standard-fijian', 'grammar-term', 'veitokoni', 'veitokoni', '', 'Adjacent nominal phrases that identify the same person or thing, without a joining word.', '', 'A type of matanauni sema: adjacent matanauni support one another in naming or identifying the same person or thing. These examples have no linking kei or se; contrast the different referents in sosoqoni.', '', 'This explanation and its use in a complete Fijian phrase need team review.', '{"comparison":"In na turaga na italatala, both phrases identify one person. Sosoqoni joins different people or things, usually with kei or se.","grammarFunction":"Adjacent nominal phrases that identify the same person or thing, without a joining word.","grammarGroup":"Noun phrase","grammarExample":"Sa tauvimate na turaga na italatala.","quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"Scan based learning explanation. OCR wording and Fijian terminology need team review before approval."}}', '[{"sourceId":"tuvavosa-review-scan-2026-10-30","section":"3.3.5"}]', '[]', 'veitokoni | adjacent nominal phrases that identify the same person or thing, without a joining word. | | a type of matanauni sema: adjacent matanauni support one another in naming or identifying the same person or thing. these examples have no linking kei or se; contrast the different referents in sosoqoni.', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('a84e220f3eef2a98', 'standard-fijian', 'grammar-term', 'kilanauni dusi', 'kilanauni-dusi', '', 'knd: a pointing form that follows and identifies a nominal base, as qo does in na siga qo.', '', 'A dusi form follows the base and other qualifiers in this pattern''s three-part order: kilanauni nauni (knn), then kilanauni vu (knv), then kilanauni dusi (knd). In na kali vesi levu qori, qori is knd. Distinguish this qualifier from a whole matanauni dusi.', '', 'This explanation and its use in a complete Fijian phrase need team review.', '{"comparison":"This points out a nominal base inside a larger phrase, as qo does in na siga qo. Matanauni dusi is itself the whole pointing phrase, such as oqo.","grammarCode":"knd","grammarFunction":"Demonstrative qualifier of a noun","grammarGroup":"Noun phrase","grammarExample":"na siga qo","marker":{"kind":"Duru qualifier","forms":"qo · qori · ya","position":"After the nominal yavu and other qualifiers.","note":"It points to the noun; it is not a whole MND on its own in this position."},"furtherLink":{"label":"Explore kilanauni dusi in Sangam Education Board - Year 13 Kilanauni worksheet","href":"https://sangamedu.ac.fj/wp-content/uploads/2021/08/Vosa-Vakaviti-Worksheet-10.pdf"},"quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"Scan based learning explanation. OCR wording and Fijian terminology need team review before approval."}}', '[{"sourceId":"tuvavosa-review-scan-2026-10-30","section":"3.4.3"},{"sourceId":"sangam-kilanauni-worksheet-2021"}]', '[]', 'kilanauni dusi | knd: a pointing form that follows and identifies a nominal base, as qo does in na siga qo. | | a dusi form follows the base and other qualifiers in this pattern''s three-part order: kilanauni nauni (knn), then kilanauni vu (knv), then kilanauni dusi (knd). in na kali vesi levu qori, qori is knd. distinguish this qualifier from a whole matanauni dusi.', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('a9dc2dd5508e94d6', 'standard-fijian', 'grammar-term', 'kilanauni nauni', 'kilanauni-nauni', '', 'knn: a nauni base that qualifies another nominal base, as vesi does in na kali vesi levu qori.', '', 'A nauni used as a duru after the main nominal base. In na kali vesi levu qori, vesi is knn. When knv and knd also occur, the order is knn, knv, knd.', '', 'This explanation and its use in a complete Fijian phrase need team review.', '{"comparison":"Here a nauni base qualifies another nominal base. In kilanauni vu, a vu or predicate base does that qualifying work instead. The role depends on the whole phrase.","grammarCode":"knn","grammarFunction":"Noun base qualifying a noun","grammarGroup":"Noun phrase","grammarExample":"Na kali vesi levu qori. Here vesi qualifies kali.","marker":{"kind":"Duru qualifier","forms":"vesi","position":"After the nominal yavu; before knv and knd if all occur.","note":"In na kali vesi levu qori, vesi is knn."},"furtherLink":{"label":"Explore kilanauni nauni in Sangam Education Board - Year 13 Kilanauni worksheet","href":"https://sangamedu.ac.fj/wp-content/uploads/2021/08/Vosa-Vakaviti-Worksheet-10.pdf"},"quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"Scan based learning explanation. OCR wording and Fijian terminology need team review before approval."}}', '[{"sourceId":"tuvavosa-review-scan-2026-10-30","section":"3.4.3"},{"sourceId":"sangam-kilanauni-worksheet-2021"},{"sourceId":"534756bd7910","page":2}]', '[]', 'kilanauni nauni | knn: a nauni base that qualifies another nominal base, as vesi does in na kali vesi levu qori. | | a nauni used as a duru after the main nominal base. in na kali vesi levu qori, vesi is knn. when knv and knd also occur, the order is knn, knv, knd.', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('a22c5d1403b8d258', 'standard-fijian', 'grammar-term', 'kilanauni vu', 'kilanauni-vu', '', 'knv: a vu base that qualifies a nominal base, as levu does in na kali vesi levu qori.', '', 'A vu used as a duru after the nominal base. In na kali vesi levu qori, levu is knv. When knn and knd also occur, the order is knn, knv, knd; this Fijian role is not simply an English adjective label.', '', 'This explanation and its use in a complete Fijian phrase need team review.', '{"comparison":"Here a vu or predicate base qualifies a nominal base. Kilanauni nauni uses a nauni base in that position instead. Check the full phrase before assigning either role.","grammarCode":"knv","grammarFunction":"Predicate base qualifying a noun","grammarGroup":"Noun phrase","grammarExample":"na kali vesi levu qori","marker":{"kind":"Duru qualifier","forms":"levu","position":"After the nominal yavu and any knn; before knd if present.","note":"In na kali vesi levu qori, levu is knv."},"furtherLink":{"label":"Explore kilanauni vu in Sangam Education Board - Year 13 Kilanauni worksheet","href":"https://sangamedu.ac.fj/wp-content/uploads/2021/08/Vosa-Vakaviti-Worksheet-10.pdf"},"quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"Scan based learning explanation. OCR wording and Fijian terminology need team review before approval."}}', '[{"sourceId":"tuvavosa-review-scan-2026-10-30","section":"3.4.3"},{"sourceId":"sangam-kilanauni-worksheet-2021"}]', '[]', 'kilanauni vu | knv: a vu base that qualifies a nominal base, as levu does in na kali vesi levu qori. | | a vu used as a duru after the nominal base. in na kali vesi levu qori, levu is knv. when knn and knd also occur, the order is knn, knv, knd; this fijian role is not simply an english adjective label.', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('3789a94865fdf769', 'standard-fijian', 'grammar-term', 'kilanauni yatuvosa', 'kilanauni-yatuvosa', '', 'clause used to qualify a nominal base', '', 'A kilanauni yatuvosa (kny) is a whole clause qualifying a nominal base, as in na kaloko [au a solia vei iko enanoa]. The base kaloko remains inside a larger matanauni; the bracketed clause narrows which clock is meant. This differs from MNYt, where the clause itself fills a nominal-phrase role.', '', 'This explanation and its use in a complete Fijian phrase need team review.', '{"comparison":"A clause adds information to a separate noun. Matanauni yatuvosa is a clause filling a nominal phrase position on its own.","grammarFunction":"Clause qualifying a noun","grammarGroup":"Noun phrase","grammarExample":"Na kaloko [au a solia vei iko enanoa].","quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"Scan based learning explanation. OCR wording and Fijian terminology need team review before approval."}}', '[{"sourceId":"tuvavosa-review-scan-2026-10-30","section":"3.4.3"},{"sourceId":"tuvavosa-matanauni-set-01-photos-2026-10-31","section":"3.4.3; P07"}]', '[]', 'kilanauni yatuvosa | clause used to qualify a nominal base | | a kilanauni yatuvosa (kny) is a whole clause qualifying a nominal base, as in na kaloko [au a solia vei iko enanoa]. the base kaloko remains inside a larger matanauni; the bracketed clause narrows which clock is meant. this differs from mnyt, where the clause itself fills a nominal-phrase role.', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('9deb0d5ba5f22545', 'standard-fijian', 'grammar-term', 'isosomi', 'isosomi', '', 'form that stands for a person already identifiable in context', '', 'Isosomi are forms used to refer to a participant. Nauni sosomi names an independent pronoun; matanauni sosomi (MNS) names the whole phrase with a mata and that pronoun. Durusau names a subject-reference role inside a matavu. A form may take a different role elsewhere, so classify the whole phrase before labeling it.', '', 'Pronoun comparison added from the founder''s first set. The existing nauni sosomi and durusau grammar charts remain intact. Individual sentence examples are pending.', '{"comparison":"Isosomi is the wider family of substitution forms. Nauni sosomi is a free pronoun; ikuri sosomi is attached; durusau is a role inside a matavu.","grammarFunction":"form that stands for a person already identifiable in context","grammarGroup":"Word building and roles","tables":[{"title":"First-person pronouns · forms and contextual uses","columns":["Use","Form","English","Number / listener"],"rows":[["Subject use · possible durusau in a matavu","au","I","singular; not applicable"],["Subject use · possible durusau in a matavu","keirau","we two, excluding you","dual; exclusive"],["Subject use · possible durusau in a matavu","keitou","we few, including a group of three, excluding you","paucal; exclusive"],["Subject use · possible durusau in a matavu","keimami","we many, excluding you","plural; exclusive"],["Short form of kedaru · subject use here","daru","we two, you and I","dual; inclusive"],["Short form of kedatou · subject use here","datou","we few, including you and me","paucal; inclusive"],["Short form of kedatou · subject use here","tou","we few, including you and me; shortened form in the appropriate context","paucal; inclusive"],["Short form of keda · subject use here","da","we many, including you and me","plural; inclusive"],["Full pronoun · nauni sosomi","kedaru","we two, you and I","dual; inclusive"],["Full pronoun · nauni sosomi","kedatou","we few, including you and me","paucal; inclusive"],["Full pronoun · nauni sosomi","keda","we many, including you and me","plural; inclusive"],["Object use","au","me","singular; not applicable"],["Object use","keirau","us two, excluding you","dual; exclusive"],["Object use","keitou","us few, three or more in a small group, excluding you","paucal; exclusive"],["Object use","keda","us many, including you and me; the group may be a village","plural; inclusive"]],"note":"These are contextual uses, not permanent word labels. Daru, datou/tou and da are shorter forms of kedaru, kedatou and keda in this set; the same spellings may be used elsewhere. Related attached endings are ikuri sosomi: ne- + -itou = neitou (exclusive); no- + -datou = nodatou and weka + -datou = wekadatou (inclusive). The suffix -itou is not the separate word tou. MNS is a whole marked pronoun phrase; durusau is a role inside a matavu. Dual = two, paucal = a few, plural = many."}],"furtherLink":{"label":"Explore isosomi in Object licensing in Fijian and the role of adjacency (2019)","href":"https://link.springer.com/article/10.1007/s11049-019-09442-1"},"quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"Pronoun comparison added from the founder''s first set. The existing nauni sosomi and durusau grammar charts remain intact. Individual sentence examples are pending."}}', '[{"sourceId":"tuvavosa-review-scan-2026-10-30","section":"3.4.4"},{"sourceId":"naisema-founder-pronouns-2026-11-01"},{"sourceId":"fijian-object-licensing-2019"},{"sourceId":"fijian-pronoun-paradigm-study"},{"sourceId":"fijian-wekadatou-acts-15-1864"}]', '[]', 'isosomi | form that stands for a person already identifiable in context | | isosomi are forms used to refer to a participant. nauni sosomi names an independent pronoun; matanauni sosomi (mns) names the whole phrase with a mata and that pronoun. durusau names a subject-reference role inside a matavu. a form may take a different role elsewhere, so classify the whole phrase before labeling it.', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('54529024a7b8984c', 'standard-fijian', 'grammar-term', 'mata ni wiliwili', 'mata-ni-wiliwili', '', 'mw: marker immediately before a quantity expression', '', 'Mata ni wiliwili (mw) immediately precedes a quantity expression in a counted phrase. E dua na gone has mw–w–m–y; kei na dua na gone has an outer m before mw–w–m–y. This construction excludes *kei e dua na gone for that construction. The same surface na can fill different roles, so classify the whole phrase and variety.', '', 'This explanation and its use in a complete Fijian phrase need team review.', '{"comparison":"Mata ni wiliwili introduces a quantity expression. Wiliwili is the quantity expression itself; neither is the whole matanauni.","grammarCode":"mw","grammarFunction":"marker immediately before a quantity expression","grammarGroup":"Noun phrase","grammarExample":"E dua na gone. / Kei na dua na gone.","quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"Scan based learning explanation. OCR wording and Fijian terminology need team review before approval."}}', '[{"sourceId":"tuvavosa-review-scan-2026-10-30","section":"3.4.1"},{"sourceId":"tuvavosa-matanauni-set-01-photos-2026-10-31","section":"3.4.1; P09"}]', '[]', 'mata ni wiliwili | mw: marker immediately before a quantity expression | | mata ni wiliwili (mw) immediately precedes a quantity expression in a counted phrase. e dua na gone has mw–w–m–y; kei na dua na gone has an outer m before mw–w–m–y. this construction excludes *kei e dua na gone for that construction. the same surface na can fill different roles, so classify the whole phrase and variety.', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('9f442cccdc76c43a', 'standard-fijian', 'grammar-term', 'taukeni nauni', 'taukeni-nauni', '', 'taukeni with a noun as the related base', '', 'For a named person (NY), this pattern teaches na + yavu + optional kilanauni + relationship marker + i + NY, yielding nei, kei, mei, or i. For a nonhuman common-noun base (NR), it illustrates na + yavu + optional kilanauni + ni + NR, as in na ulu ni vuaka. Ni alone does not distinguish action, topic, intended use, consumption, body part, or offspring. Check other human common-noun patterns separately.', '', 'This explanation and its use in a complete Fijian phrase need team review.', '{"comparison":"Taukeni nauni relates a nominal base to an owner or other participant; taukeni sosomi uses a pronoun-related form instead.","grammarFunction":"taukeni with a noun as the related base","grammarGroup":"Noun phrase","grammarExample":"Sa boro na vale nei Luke.","tables":[{"title":"Matanauni taukeni · named-person relationships","columns":["Tuvavosa relationship","Marker before NY","Example from this pattern","What English needs to say"],"rows":[["Taukeni dina / raraba","nei","na vale nei Luke","Luke owns the house; with other bases, he may make or perform it"],["Taukeni bale","kei","na sere kei Lia","a song about Lia, or otherwise directed toward her"],["Taukeni kana","kei","na dalo kei Sami","taro for Sami to eat"],["Taukeni gunu","mei","na yaqona mei Tui","yaqona for Tui to drink"],["Taukeni kuri","i","na luve i Jo","Jo''s child; direct body-part and kinship relation"]],"note":"NY means nauni yaca (a named person). The same kei form may express bale or kana; decide from the yavu and the intended relationship. The example wording needs team review."},{"title":"Matanauni taukeni · common-noun relationships","columns":["Relationship to interpret","Marker before NR","Example in this pattern","Possible English reading"],"rows":[["Action or sound produced","ni","na kudru ni vuaka","the pig''s grunt"],["About the second noun","ni","na italanoa ni vuaka","a story about the pig"],["Intended for the second noun","ni","na moto ni vuaka","a spear for a pig"],["The second noun consumes the first","ni","na benu ni vuaka; na wai ni vuaka","refuse for the pig to eat; water for the pig to drink"],["Body-part relationship","ni","na ulu ni vuaka","the pig''s head"],["Offspring relationship","ni","na luve ni vuaka","the pig''s offspring"]],"note":"NR means nauni raraba (common-noun base). The phrase wording needs team review. Ni does not by itself tell you which English relationship to use. Na vale ni koli illustrates a nonhuman common-noun pattern; human common-noun owners need separate review."}],"furtherLink":{"label":"Explore taukeni nauni in QMUL GLOW 42: Fijian possessive classifiers as nominal Appl heads","href":"https://glowlinguistics.org/42/wp-content/uploads/sites/4/2019/03/GLOW_FJPoss.pdf"},"quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"Source-led Tuvavosa learning explanation. The supplied scan and independent analyses support the pattern; wording and sentence examples still need team review."}}', '[{"sourceId":"tuvavosa-review-scan-2026-10-30","section":"3.5.2"},{"sourceId":"qmul-fijian-possession-2019"},{"sourceId":"qmul-fijian-noun-phrase-2019"}]', '[]', 'taukeni nauni | taukeni with a noun as the related base | | for a named person (ny), this pattern teaches na + yavu + optional kilanauni + relationship marker + i + ny, yielding nei, kei, mei, or i. for a nonhuman common-noun base (nr), it illustrates na + yavu + optional kilanauni + ni + nr, as in na ulu ni vuaka. ni alone does not distinguish action, topic, intended use, consumption, body part, or offspring. check other human common-noun patterns separately.', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('0d7ab485d084664d', 'standard-fijian', 'grammar-term', 'taukeni sosomi', 'taukeni-sosomi', '', 'possession expressed with an understood owner', '', 'When the itaukei is already understood, an attached kuri sosomi identifies person and number. For taukeni dina/raraba, bale, kana, or gunu, the teaching order is na + (ikuri taukeni + ikuri sosomi) + optional dui + yavu. The first element is no-/ne-, ke-, or me-, chosen by relationship; for example no- + -mu gives nomu. Taukeni kuri differs: na + yavu + k, with the suffix after the yavu. Do not substitute an independent pronoun into the named-person or common-noun pattern.', '', 'This explanation and its use in a complete Fijian phrase need team review.', '{"comparison":"Taukeni sosomi uses an understood owner and an ikuri sosomi; taukeni nauni names a nominal owner. Neitou and nodatou differ in who is included.","grammarFunction":"possession expressed with an understood owner","grammarGroup":"Noun phrase","grammarExample":"na nomu lako; na neimami dui vale; na yavaqu","tables":[{"title":"Kuri sosomi · VR (attached person/number forms)","columns":["Wiliwili · number","Qo · speaker, listener excluded","Qori · listener","Ya · third person","Okati · speaker and listener"],"rows":[["Dua · one","-qu","-mu","-na","—"],["Rua · two","-irau","-mudrau","-drau","-daru"],["Vica · a few","-itou","-mudou","-dratou","-datou"],["Levu · many","-imami","-muni","-dra","-da"]],"note":"Attached person-and-number endings: neitou = ne- + -itou (exclusive); nodatou = no- + -datou (inclusive). Wekadatou has -datou after weka, a different position from the preposed possessive forms. The original person/number rows remain above."},{"title":"Taukeni sosomi · first element and relationship","columns":["Relationship","Ikuri taukeni","Example from this pattern","How to read it"],"rows":[["Taukeni dina / raraba","no-/ne-","na nomu lako; na neimami dui vale","the known person''s action or property"],["Taukeni bale","ke-","na kena italanoa; na keda vere","about, for, or affecting the known person/group"],["Taukeni kana","ke-","na keimami uvi","food for the known group to eat"],["Taukeni gunu","me-","na memudou ti","a drink for the known group to drink"],["Taukeni kuri","none before yavu","na yavaqu; na makubuna","na + yavu + k: attach kuri sosomi after the base"]],"note":"The first four rows use na + (ikuri taukeni + ikuri sosomi) + (dui) + yavu. Taukeni kuri instead uses na + yavu + k. The example meanings need team review."}],"furtherLink":{"label":"Explore taukeni sosomi in QMUL and Padova: Fijian Possession in the Noun Phrase","href":"https://pietrobaggio.wordpress.com/wp-content/uploads/2019/03/igg_handout___unabridged.pdf"},"quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"Source-led Tuvavosa learning explanation. The supplied scan and independent analyses support the pattern; wording and sentence examples still need team review."}}', '[{"sourceId":"tuvavosa-review-scan-2026-10-30","section":"3.5.3"},{"sourceId":"qmul-fijian-noun-phrase-2019"}]', '[]', 'taukeni sosomi | possession expressed with an understood owner | | when the itaukei is already understood, an attached kuri sosomi identifies person and number. for taukeni dina/raraba, bale, kana, or gunu, the teaching order is na + (ikuri taukeni + ikuri sosomi) + optional dui + yavu. the first element is no-/ne-, ke-, or me-, chosen by relationship; for example no- + -mu gives nomu. taukeni kuri differs: na + yavu + k, with the suffix after the yavu. do not substitute an independent pronoun into the named-person or common-noun pattern.', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('df5d3cd7ba370722', 'standard-fijian', 'grammar-term', 'nauni taukeni kuri', 'nauni-taukeni-kuri', '', 'relational nominal base used with a direct possessive addition', '', 'A nauni taukeni kuri is a base that licenses direct possessive attachment in a particular construction. The pattern gives na yavaqu and na makubuna; for speaker-exclusive dual, few and many it contrasts preposed neirau/neitou/neimami with directly suffixed forms containing -ikeirau/-ikeitou/-ikeimami, such as na dakuikeirau. Some kin/body-related bases do not allow this direct form; check a complete attested word before building one.', '', 'This explanation and its use in a complete Fijian phrase need team review.', '{"comparison":"This is a nominal base that can take a direct possessive ending in a licensed construction; taukeni kuri names the relationship, not the base.","grammarFunction":"relational nominal base used with a direct possessive addition","grammarGroup":"Noun phrase","grammarExample":"Na yavaqu. / Na makubuna. / Na dakuikeirau.","tables":[{"title":"Kuri sosomi · VR (attached person/number forms)","columns":["Wiliwili · number","Qo · speaker, listener excluded","Qori · listener","Ya · third person","Okati · speaker and listener"],"rows":[["Dua · one","-qu","-mu","-na","—"],["Rua · two","-irau","-mudrau","-drau","-daru"],["Vica · a few","-itou","-mudou","-dratou","-datou"],["Levu · many","-imami","-muni","-dra","-da"]],"note":"These attached forms show different person and number combinations. These are not independent nauni sosomi. The inclusive okati column has no singular. Team review is still required for example wording."}],"furtherLink":{"label":"Explore nauni taukeni kuri in QMUL GLOW 42: Fijian possessive classifiers as nominal Appl heads","href":"https://glowlinguistics.org/42/wp-content/uploads/sites/4/2019/03/GLOW_FJPoss.pdf"},"quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"Source-led Tuvavosa learning explanation. The supplied scan and independent analyses support the pattern; wording and sentence examples still need team review."}}', '[{"sourceId":"tuvavosa-review-scan-2026-10-30","section":"3.5.4"},{"sourceId":"qmul-fijian-possession-2019"},{"sourceId":"fijian-tama-i-jone-example"},{"sourceId":"tuvavosa-matanauni-set-01-photos-2026-10-31","section":"3.5.4; P01"}]', '[]', 'nauni taukeni kuri | relational nominal base used with a direct possessive addition | | a nauni taukeni kuri is a base that licenses direct possessive attachment in a particular construction. the pattern gives na yavaqu and na makubuna; for speaker-exclusive dual, few and many it contrasts preposed neirau/neitou/neimami with directly suffixed forms containing -ikeirau/-ikeitou/-ikeimami, such as na dakuikeirau. some kin/body-related bases do not allow this direct form; check a complete attested word before building one.', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('2e95dc7a7f565299', 'standard-fijian', 'grammar-term', 'ikuri taukeni', 'ikuri-taukeni', '', 'first bound element in a preposed taukeni sosomi form', '', 'In taukeni sosomi, no-/ne-, ke-, or me- precedes an attached person/number form: no- + -mu gives nomu, ke- + -qu gives kequ, and me- + -mudou gives memudou. The combination precedes the yavu. The element marks the relationship, while the suffix identifies the understood owner. Taukeni kuri instead uses na + yavu + k.', '', 'This explanation and its use in a complete Fijian phrase need team review.', '{"comparison":"Ikuri taukeni (such as no-/ne-, ke-, or me-) selects the possessive relationship; ikuri sosomi identifies the person and number.","grammarFunction":"first bound element in a preposed taukeni sosomi form","grammarGroup":"Word building and roles","grammarExample":"na nomu lako; na keimami uvi; na memudou ti","tables":[{"title":"Taukeni sosomi · first element and relationship","columns":["Relationship","Ikuri taukeni","Example from this pattern","How to read it"],"rows":[["Taukeni dina / raraba","no-/ne-","na nomu lako; na neimami dui vale","the known person''s action or property"],["Taukeni bale","ke-","na kena italanoa; na keda vere","about, for, or affecting the known person/group"],["Taukeni kana","ke-","na keimami uvi","food for the known group to eat"],["Taukeni gunu","me-","na memudou ti","a drink for the known group to drink"],["Taukeni kuri","none before yavu","na yavaqu; na makubuna","na + yavu + k: attach kuri sosomi after the base"]],"note":"The first four rows use na + (ikuri taukeni + ikuri sosomi) + (dui) + yavu. Taukeni kuri instead uses na + yavu + k. The example meanings need team review."}],"furtherLink":{"label":"Explore ikuri taukeni in QMUL GLOW 42: Fijian possessive classifiers as nominal Appl heads","href":"https://glowlinguistics.org/42/wp-content/uploads/sites/4/2019/03/GLOW_FJPoss.pdf"},"quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"Source-led Tuvavosa learning explanation. The supplied scan and independent analyses support the pattern; wording and sentence examples still need team review."}}', '[{"sourceId":"tuvavosa-review-scan-2026-10-30","section":"3.5.3"},{"sourceId":"qmul-fijian-possession-2019"},{"sourceId":"qmul-fijian-noun-phrase-2019"}]', '[]', 'ikuri taukeni | first bound element in a preposed taukeni sosomi form | | in taukeni sosomi, no-/ne-, ke-, or me- precedes an attached person/number form: no- + -mu gives nomu, ke- + -qu gives kequ, and me- + -mudou gives memudou. the combination precedes the yavu. the element marks the relationship, while the suffix identifies the understood owner. taukeni kuri instead uses na + yavu + k.', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('1afc9d35ae542341', 'standard-fijian', 'grammar-term', 'ikuri sosomi', 'ikuri-sosomi', '', 'attached person/number form used in taukeni sosomi', '', 'Ikuri sosomi (kuri sosomi) is an attached person-and-number ending. In neitou, ne- joins exclusive -itou; in nodatou, no- joins inclusive -datou. In wekadatou, -datou follows the nominal base weka. The attached ending is a different use from an independent nauni sosomi or a separate shortened pronoun form; the preceding base or possessive element determines the construction.', '', 'This explanation and its use in a complete Fijian phrase need team review.', '{"comparison":"Neitou contains exclusive -itou; nodatou and wekadatou contain inclusive -datou. Free tou and attached -itou must not be treated as the same form.","grammarFunction":"attached person/number form used in taukeni sosomi","grammarGroup":"Word building and roles","grammarExample":"neitou = ne- + -itou; nodatou = no- + -datou; wekadatou = weka + -datou","tables":[{"title":"Kuri sosomi · VR (attached person/number forms)","columns":["Wiliwili · number","Qo · speaker, listener excluded","Qori · listener","Ya · third person","Okati · speaker and listener"],"rows":[["Dua · one","-qu","-mu","-na","—"],["Rua · two","-irau","-mudrau","-drau","-daru"],["Vica · a few","-itou","-mudou","-dratou","-datou"],["Levu · many","-imami","-muni","-dra","-da"]],"note":"These are attached person-and-number endings. Exclusive -itou appears in neitou; inclusive -datou appears in nodatou and after weka in wekadatou. Free tou is not the suffix -itou. Keep the original person/number rows and check each whole word in context."}],"furtherLink":{"label":"Explore ikuri sosomi in QMUL and Padova: Fijian Possession in the Noun Phrase","href":"https://pietrobaggio.wordpress.com/wp-content/uploads/2019/03/igg_handout___unabridged.pdf"},"quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"Source-led Tuvavosa learning explanation. The supplied scan and independent analyses support the pattern; wording and sentence examples still need team review."}}', '[{"sourceId":"tuvavosa-review-scan-2026-10-30","section":"3.5.3"},{"sourceId":"qmul-fijian-noun-phrase-2019"},{"sourceId":"naisema-founder-pronouns-2026-11-01"},{"sourceId":"fijian-pronoun-paradigm-study"},{"sourceId":"fijian-wekadatou-acts-15-1864"}]', '[]', 'ikuri sosomi | attached person/number form used in taukeni sosomi | | ikuri sosomi (kuri sosomi) is an attached person-and-number ending. in neitou, ne- joins exclusive -itou; in nodatou, no- joins inclusive -datou. in wekadatou, -datou follows the nominal base weka. the attached ending is a different use from an independent nauni sosomi or a separate shortened pronoun form; the preceding base or possessive element determines the construction.', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('65718beb462d833d', 'standard-fijian', 'grammar-term', 'vumatua', 'vumatua', '', 'vaka- derived form with an intensified action sense', '', 'One use of vaka-. Its interpretation depends on the base and the complete expression.', '', 'This explanation and its use in a complete Fijian phrase need team review.', '{"comparison":"Vumatua can intensify an action; vuvakavu makes or causes a state or event. Similar vaka- spelling does not make the functions identical.","grammarFunction":"vaka- derived form with an intensified action sense","grammarGroup":"Word building and roles","quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"Scan based learning explanation. OCR wording and Fijian terminology need team review before approval."}}', '[{"sourceId":"tuvavosa-review-scan-2026-10-30","section":"4.3.3"}]', '[]', 'vumatua | vaka- derived form with an intensified action sense | | one use of vaka-. its interpretation depends on the base and the complete expression.', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('c688890b56e0c75b', 'standard-fijian', 'grammar-term', 'vuvakavu', 'vuvakavu', '', 'vaka- derived form expressing causation', '', 'One possible use of vaka- is to express causing a state or event. Other uses of vaka- must not be collapsed into this one.', '', 'This explanation and its use in a complete Fijian phrase need team review.', '{"comparison":"Vuvakavu expresses causation; vumatua expresses intensity. Confirm the whole derived word before choosing either analysis.","grammarFunction":"vaka- derived form expressing causation","grammarGroup":"Word building and roles","quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"Scan based learning explanation. OCR wording and Fijian terminology need team review before approval."}}', '[{"sourceId":"tuvavosa-review-scan-2026-10-30","section":"4.3.3"}]', '[]', 'vuvakavu | vaka- derived form expressing causation | | one possible use of vaka- is to express causing a state or event. other uses of vaka- must not be collapsed into this one.', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('f17c0f9f86f03762', 'standard-fijian', 'grammar-term', 'vuveisoli', 'vuveisoli', '', 'vei- derived form expressing reciprocal action', '', 'For some bases, vei- can describe action exchanged between participants. There are also other uses of vei-.', '', 'This explanation and its use in a complete Fijian phrase need team review.', '{"comparison":"Vuveisoli expresses participants acting on each other; vuvakavu expresses causation. The prefixes vei- and vaka- do different work.","grammarFunction":"vei- derived form expressing reciprocal action","grammarGroup":"Word building and roles","quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"Scan based learning explanation. OCR wording and Fijian terminology need team review before approval."}}', '[{"sourceId":"tuvavosa-review-scan-2026-10-30","section":"4.3.2"}]', '[]', 'vuveisoli | vei- derived form expressing reciprocal action | | for some bases, vei- can describe action exchanged between participants. there are also other uses of vei-.', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('895bd07461b6bbf4', 'standard-fijian', 'grammar-term', 'druabalavu', 'druabalavu', '', 'repetition of a longer part of a base', '', 'A reduplication pattern. Its meaning varies with the base and context.', '', 'This explanation and its use in a complete Fijian phrase need team review.', '{"comparison":"Druabalavu repeats a longer span of the base; drualeka repeats a shorter span. The meaning of repetition still depends on the word and phrase.","grammarFunction":"repetition of a longer part of a base","grammarGroup":"Word building and roles","quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"Scan based learning explanation. OCR wording and Fijian terminology need team review before approval."}}', '[{"sourceId":"tuvavosa-review-scan-2026-10-30","section":"4.3.5"}]', '[]', 'druabalavu | repetition of a longer part of a base | | a reduplication pattern. its meaning varies with the base and context.', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
