INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('88d1f74da258ec29', 'standard-fijian', 'grammar-term', 'drualeka', 'drualeka', '', 'repetition of a shorter part of a base', '', 'A reduplication pattern. Do not infer a single fixed meaning from the form alone.', '', 'This explanation and its use in a complete Fijian phrase need team review.', '{"comparison":"Drualeka repeats a shorter span; druabalavu repeats a longer span. Do not infer frequency or intensity from length alone.","grammarFunction":"repetition of a shorter part of a base","grammarGroup":"Word building and roles","quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"Scan based learning explanation. OCR wording and Fijian terminology need team review before approval."}}', '[{"sourceId":"tuvavosa-review-scan-2026-10-30","section":"4.3.5"}]', '[]', 'drualeka | repetition of a shorter part of a base | | a reduplication pattern. do not infer a single fixed meaning from the form alone.', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
