INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('9da44599c891a504', 'standard-fijian', 'grammar-term', 'dewaleka', 'dewaleka', '', 'shorter dewa ending on a predicate base', '', 'The shorter dewa family has -a and -i forms in this pattern. Which one appears depends on the complete base and construction; it cannot be chosen mechanically from an English translation.', '', 'This explanation and its use in a complete Fijian phrase need team review.', '{"comparison":"Dewaleka is the shorter dewa ending; dewabalavu is the longer ending. Koso dewa concerns a connecting consonant, not the ending''s length.","grammarFunction":"shorter dewa ending on a predicate base","grammarGroup":"Predicate phrase","grammarExample":"Mokuta. / Mokuti.","quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"Scan based learning explanation. OCR wording and Fijian terminology need team review before approval."}}', '[{"sourceId":"tuvavosa-review-scan-2026-10-30","section":"4.4.2"},{"sourceId":"tuvavosa-4-4-4-5-photos-2026-10-31","section":"4.4.2"}]', '[]', 'dewaleka | shorter dewa ending on a predicate base | | the shorter dewa family has -a and -i forms in this pattern. which one appears depends on the complete base and construction; it cannot be chosen mechanically from an english translation.', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('df569818ce694e2e', 'standard-fijian', 'grammar-term', 'dewabalavu', 'dewabalavu', '', 'longer dewa ending on a predicate base', '', 'The longer dewa family has -aka and -aki forms in this pattern. These forms differ with shorter forms and shows that the relationship expressed can change; check the actual base and phrase.', '', 'This explanation and its use in a complete Fijian phrase need team review.', '{"comparison":"Dewabalavu is the longer dewa ending; dewaleka is shorter. The chosen ending and participant relation need an attested form.","grammarFunction":"longer dewa ending on a predicate base","grammarGroup":"Predicate phrase","grammarExample":"Mokulaka. / Mokulaki.","quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"Scan based learning explanation. OCR wording and Fijian terminology need team review before approval."}}', '[{"sourceId":"tuvavosa-review-scan-2026-10-30","section":"4.4.2"},{"sourceId":"tuvavosa-4-4-4-5-photos-2026-10-31","section":"4.4.2"}]', '[]', 'dewabalavu | longer dewa ending on a predicate base | | the longer dewa family has -aka and -aki forms in this pattern. these forms differ with shorter forms and shows that the relationship expressed can change; check the actual base and phrase.', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('4db85172d75f0815', 'standard-fijian', 'grammar-term', 'koso dewa', 'koso-dewa', '', 'consonant connecting a base and dewa ending', '', 'Some dewa forms have a consonant between the vu base and ending. The forms include different consonants for short and long forms, plus vowel-final forms and exceptions. Store the attested whole word; the list is not a spelling algorithm.', '', 'This explanation and its use in a complete Fijian phrase need team review.', '{"comparison":"Koso dewa is a connecting consonant between base and dewa. It is neither the base nor the dewa ending itself.","grammarFunction":"consonant connecting a base and dewa ending","grammarGroup":"Word building and roles","grammarExample":"Raica. / Ciciva.","quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"Scan based learning explanation. OCR wording and Fijian terminology need team review before approval."}}', '[{"sourceId":"tuvavosa-review-scan-2026-10-30","section":"4.4.3"},{"sourceId":"tuvavosa-4-4-4-5-photos-2026-10-31","section":"4.4.3"}]', '[]', 'koso dewa | consonant connecting a base and dewa ending | | some dewa forms have a consonant between the vu base and ending. the forms include different consonants for short and long forms, plus vowel-final forms and exceptions. store the attested whole word; the list is not a spelling algorithm.', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('fc856b58902e36aa', 'standard-fijian', 'grammar-term', 'vuwale', 'vuwale', '', 'predicate base used without a dewa ending', '', 'A vu used without a dewa ending in the construction being analysed. In the photographed classification it cannot take the nauni qali pattern. A related derived word may still have dewa, so classify this use rather than every similar spelling.', '', 'This explanation and its use in a complete Fijian phrase need team review.', '{"comparison":"A vuwale is used without a dewa ending. A vu dewa has a dewa ending; the contrast may change which participant the predicate connects to.","grammarFunction":"predicate base used without a dewa ending","grammarGroup":"Predicate phrase","quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"Scan based learning explanation. OCR wording and Fijian terminology need team review before approval."}}', '[{"sourceId":"tuvavosa-review-scan-2026-10-30","section":"4.4.4"},{"sourceId":"tuvavosa-4-4-4-5-photos-2026-10-31","section":"4.4.4"}]', '[]', 'vuwale | predicate base used without a dewa ending | | a vu used without a dewa ending in the construction being analysed. in the photographed classification it cannot take the nauni qali pattern. a related derived word may still have dewa, so classify this use rather than every similar spelling.', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('6577eb6e11065506', 'standard-fijian', 'grammar-term', 'vu dewa', 'vu-dewa', '', 'predicate base with a dewa ending', '', 'A family of vu with dewa forms. The dewa classes distinguishes vucoko, vūtū and vusaumaki by whether a bare base is possible and whether the sau stays aligned across the two constructions.', '', 'This explanation and its use in a complete Fijian phrase need team review.', '{"comparison":"A vu dewa has a dewa ending linked to its participant pattern. A vuwale is used without that ending. The difference is not simply English past versus present tense.","grammarFunction":"predicate base with a dewa ending","grammarGroup":"Predicate phrase","grammarExample":"E cici. / E ciciva.","tables":[{"title":"Mataqali vu dewa","columns":["Fijian class","Plain English guide","Diagnostic"],"rows":[["vucoko","bound dewa form","the pattern does not use the bare base alone"],["vūtū","same sau","the base can stand alone; the sau remains aligned"],["vusaumaki","shifted sau","the participant role changes across the contrast"]],"note":"Use attested paired phrases. These labels are not substitutes for English noun/verb tags."}],"quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"Scan based learning explanation. OCR wording and Fijian terminology need team review before approval."}}', '[{"sourceId":"tuvavosa-review-scan-2026-10-30","section":"4.4.4"},{"sourceId":"tuvavosa-4-4-4-5-photos-2026-10-31","section":"4.4.4"}]', '[]', 'vu dewa | predicate base with a dewa ending | | a family of vu with dewa forms. the dewa classes distinguishes vucoko, vutu and vusaumaki by whether a bare base is possible and whether the sau stays aligned across the two constructions.', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('2602dc68f17b216b', 'standard-fijian', 'grammar-term', 'vucoko', 'vucoko', '', 'predicate base whose dewa ending remains attached', '', 'A vu dewa class whose form is bound to its dewa ending in this teaching analysis. Examples include nanuma/nanumi and excludes treating an invented bare *nanu as a complete equivalent.', '', 'This explanation and its use in a complete Fijian phrase need team review.', '{"comparison":"In a vucoko contrast, the dewa ending does not change the named actor; vusaumaki changes how participant roles align. Check both complete forms.","grammarFunction":"predicate base whose dewa ending remains attached","grammarGroup":"Predicate phrase","grammarExample":"Au nanuma na matana. / Au nanumi koya.","quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"Scan based learning explanation. OCR wording and Fijian terminology need team review before approval."}}', '[{"sourceId":"tuvavosa-review-scan-2026-10-30","section":"4.4.4"},{"sourceId":"tuvavosa-4-4-4-5-photos-2026-10-31","section":"4.4.4"}]', '[]', 'vucoko | predicate base whose dewa ending remains attached | | a vu dewa class whose form is bound to its dewa ending in this teaching analysis. examples include nanuma/nanumi and excludes treating an invented bare *nanu as a complete equivalent.', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('8fcea57b3c5eb6d3', 'standard-fijian', 'grammar-term', 'vusaumaki', 'vusaumaki', '', 'predicate base whose participant roles shift with a dewa ending', '', 'A vu dewa class where the sau of the bare predicate and the affected participant of its dewa form do not align in the same way. Examples use sogo/sogota as a contrast; review both full constructions before assigning the class.', '', 'This explanation and its use in a complete Fijian phrase need team review.', '{"comparison":"In a vusaumaki contrast, participant roles shift with dewa; in vucoko the actor remains aligned. The English verb alone cannot show this distinction.","grammarFunction":"predicate base whose participant roles shift with a dewa ending","grammarGroup":"Predicate phrase","grammarExample":"E sogo. / E sogota.","quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"Scan based learning explanation. OCR wording and Fijian terminology need team review before approval."}}', '[{"sourceId":"tuvavosa-review-scan-2026-10-30","section":"4.4.4"},{"sourceId":"tuvavosa-4-4-4-5-photos-2026-10-31","section":"4.4.4"}]', '[]', 'vusaumaki | predicate base whose participant roles shift with a dewa ending | | a vu dewa class where the sau of the bare predicate and the affected participant of its dewa form do not align in the same way. examples use sogo/sogota as a contrast; review both full constructions before assigning the class.', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('d607fee846cbae00', 'standard-fijian', 'grammar-term', 'kilavu nauni', 'kilavu-nauni', '', 'A nauni base that qualifies a predicate, as yaqona does after gunu in au gunu yaqona tiko.', '', 'A nauni base may follow a vu and narrow the kind of action or event. In au gunu yaqona tiko, yaqona is kilavu nauni (kvn); it is not analyzed as nauni qali. Examples also include forms with dewa, so absence of dewa is not an absolute test.', '', 'This explanation and its use in a complete Fijian phrase need team review.', '{"comparison":"A nominal base qualifies the predicate, as yaqona does after gunu in au gunu yaqona tiko. Kilavu vu uses a predicate base to qualify another predicate.","grammarCode":"kvn","grammarFunction":"Noun base qualifying a predicate","grammarGroup":"Predicate phrase","grammarExample":"Au gunu yaqona tiko.","marker":{"kind":"Duru qualifier","forms":"yaqona","position":"After the predicate yavu.","note":"In au gunu yaqona tiko, yaqona is kvn."},"quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"Scan based learning explanation. OCR wording and Fijian terminology need team review before approval."}}', '[{"sourceId":"tuvavosa-review-scan-2026-10-30","section":"4.5.2"},{"sourceId":"tuvavosa-4-4-4-5-photos-2026-10-31","section":"4.5.2"}]', '[]', 'kilavu nauni | a nauni base that qualifies a predicate, as yaqona does after gunu in au gunu yaqona tiko. | | a nauni base may follow a vu and narrow the kind of action or event. in au gunu yaqona tiko, yaqona is kilavu nauni (kvn); it is not analyzed as nauni qali. examples also include forms with dewa, so absence of dewa is not an absolute test.', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('32c8313b4d4dfa81', 'standard-fijian', 'grammar-term', 'kilavu vu', 'kilavu-vu', '', 'A vu base that qualifies another predicate, as vinaka does after bula in Oni bula vinaka sara.', '', 'A vu base may qualify the main predicate within a matavu. In oni bula vinaka sara, vinaka is kilavu vu (kvv) and sara is a following durumuri. A copied English adverb tag does not establish the Fijian role.', '', 'This explanation and its use in a complete Fijian phrase need team review.', '{"comparison":"A predicate base qualifies another predicate, as vinaka does after bula in Oni bula vinaka sara. Kilavu nauni uses a nominal base in that position.","grammarCode":"kvv","grammarFunction":"Predicate base qualifying another predicate","grammarGroup":"Predicate phrase","grammarExample":"Oni bula vinaka sara.","marker":{"kind":"Duru qualifier","forms":"vinaka","position":"After the predicate yavu.","note":"In Oni bula vinaka sara, vinaka is kvv."},"quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"Scan based learning explanation. OCR wording and Fijian terminology need team review before approval."}}', '[{"sourceId":"tuvavosa-review-scan-2026-10-30","section":"4.5.3"},{"sourceId":"534756bd7910","page":3},{"sourceId":"tuvavosa-4-4-4-5-photos-2026-10-31","section":"4.5.3"}]', '[]', 'kilavu vu | a vu base that qualifies another predicate, as vinaka does after bula in oni bula vinaka sara. | | a vu base may qualify the main predicate within a matavu. in oni bula vinaka sara, vinaka is kilavu vu (kvv) and sara is a following durumuri. a copied english adverb tag does not establish the fijian role.', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('81ba51a610617215', 'standard-fijian', 'grammar-term', 'nauni raraba', 'nauni-raraba', '', 'A common nominal base naming a kind of person, place, thing, or idea, such as vale; it differs from the whole phrase na vale.', '', 'A nauni naming a general kind of person, thing or place, as distinct from a proper name. Its role in a sentence still depends on the surrounding matanauni.', '', 'Check spelling and current use in a complete Fijian phrase before approving it.', '{"comparison":"Nauni raraba names a common noun base, such as vale. Matanauni raraba names a whole phrase with na, such as na vale.","grammarFunction":"A common nominal base naming a kind of person, place, thing, or idea, such as vale; it differs from the whole phrase na vale.","grammarGroup":"Noun phrase","grammarExample":"Na vale levu qo.","furtherLink":{"label":"Explore nauni raraba in Salavata ni Nanuma Lesu 10 - teacher''s guide, page 42","href":"https://fliphtml5.com/gjgbb/znkq/Year_10_SALAVATA_NI_NANUMA_LESU_10_Teacher_s_Guide/42/"},"quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"Fijian term checked against the local scan image. The English explanation remains subject to team review. The photographed Tuvavosa section and the independent Year 10 teacher''s guide separate nauni raraba from names. The whole phrase is classified separately as matanauni raraba."}}', '[{"sourceId":"tuvavosa-review-scan-2026-10-30","section":"3.4.2"},{"sourceId":"nanuma-lesu-year10-nauni-raraba"}]', '[]', 'nauni raraba | a common nominal base naming a kind of person, place, thing, or idea, such as vale; it differs from the whole phrase na vale. | | a nauni naming a general kind of person, thing or place, as distinct from a proper name. its role in a sentence still depends on the surrounding matanauni.', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('fb559c8e7987559a', 'standard-fijian', 'grammar-term', 'kilavu tale', 'kilavu-tale', '', 'later predicate qualifier', '', 'The pattern permits some vaka-/vā- derived kilavu after a durumuri and also in the earlier kilavu slot. Other kilavu cannot be moved there. Record the actual word and order from a checked phrase.', '', 'Check spelling and current use in a complete Fijian phrase before approving it.', '{"comparison":"Kilavu tale occupies a later qualifier position; other kilavu can occur earlier. The position is part of the Fijian analysis, not an English adverb label.","grammarFunction":"later predicate qualifier","grammarGroup":"Predicate phrase","grammarExample":"Drau lako mai vakatotolo. / Drau lako vakatotolo mai.","quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"Fijian term checked against the local scan image. The English explanation remains subject to team review."}}', '[{"sourceId":"tuvavosa-review-scan-2026-10-30","section":"4.5.5"},{"sourceId":"tuvavosa-4-4-4-5-photos-2026-10-31","section":"4.5.5"}]', '[]', 'kilavu tale | later predicate qualifier | | the pattern permits some vaka-/va- derived kilavu after a durumuri and also in the earlier kilavu slot. other kilavu cannot be moved there. record the actual word and order from a checked phrase.', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('balawa-pandanus-20261030', 'standard-fijian', 'word', 'Balawa', 'balawa', 'noun', 'A pandanus or screw pine plant, whose leaves can be used for weaving.', '', '', '', 'Botanical and development sources independently identify balawa as pandanus. Plant species and regional use need NAISEMA review.', '{"comparison":"This identified balawa is Pandanus tectorius, called hala in Hawaiʻi. Its fruit resembles a pineapple, but pineapple is a different plant.","scientificName":"Pandanus tectorius","identificationNote":"one documented identification","furtherLink":{"label":"Explore Balawa in JICA · Fiji study report","href":"https://openjicareport.jica.go.jp/pdf/12263562_05.pdf"},"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"Botanical and development sources independently identify balawa as pandanus. Plant species and regional use need NAISEMA review."}}', '[{"sourceId":"balawa-jica"},{"sourceId":"balawa-usp"},{"sourceId":"fiji-marinas-pandanus-guide"},{"sourceId":"hawaii-native-plants-hala"}]', '[]', 'balawa | a pandanus or screw pine plant, whose leaves can be used for weaving. | |', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('balawa-fruit-20261030', 'standard-fijian', 'word', 'Balawa', 'balawa', 'noun', 'The fruit of a balawa pandanus plant.', '', '', '', 'A modern dictionary records this use; the independent sources establish the plant and its fruit, but this exact Fijian fruit sense still needs a speaker or phrase check.', '{"furtherLink":{"label":"Explore Balawa in JICA · Fiji study report","href":"https://openjicareport.jica.go.jp/pdf/12263562_05.pdf"},"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"A modern dictionary records this use; the independent sources establish the plant and its fruit, but this exact Fijian fruit sense still needs a speaker or phrase check."}}', '[{"sourceId":"balawa-jica"},{"sourceId":"balawa-usp"}]', '["plants"]', 'balawa | the fruit of a balawa pandanus plant. | |', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('balawa-pineapple-20261030', 'standard-fijian', 'word', 'Balawa', 'balawa', 'noun', 'A pineapple; this use can depend on place and context.', '', '', '', 'FAO lists balawa as a common name for pineapple; a modern Fijian dictionary also describes this use. Regional usage and example phrase need NAISEMA review.', '{"furtherLink":{"label":"Explore Balawa in FAO Ecocrop · Pineapple","href":"https://ecocrop.apps.fao.org/ecocrop/srv/en/cropView?id=402"},"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"FAO lists balawa as a common name for pineapple; a modern Fijian dictionary also describes this use. Regional usage and example phrase need NAISEMA review."}}', '[{"sourceId":"balawa-fao"}]', '[]', 'balawa | a pineapple; this use can depend on place and context. | |', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('batikadi-person-20261030', 'standard-fijian', 'word', 'Batikadi', 'batikadi', 'noun', 'An ambusher or armed fighter; older sources also use the word for a kidnapper.', '', '', '', 'The historical page gives kidnapper as a noun; current Fijian reporting uses batikadi for an armed group. Exact modern range needs team review.', '{"furtherLink":{"label":"Explore Batikadi in The Fiji Times · Batikadi in current reporting","href":"https://www.fijitimes.com.fj/vakatakilai-koya-na-komupiuta/"},"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"The historical page gives kidnapper as a noun; current Fijian reporting uses batikadi for an armed group. Exact modern range needs team review."}}', '[{"sourceId":"a2056948d246","page":18},{"sourceId":"batikadi-fiji-times"}]', '[]', 'batikadi | an ambusher or armed fighter; older sources also use the word for a kidnapper. | |', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('bogi-ni-gone-20261030', 'standard-fijian', 'word', 'bogi ni gone', 'bogi-ni-gone', 'noun phrase', 'The soft spot or crown of a young child’s head.', '', '', '', 'Historical page 20 describes the soft area where the skull bones have not closed. A second historical handbook gives the crown of the head. Anatomy and present-day use need review.', '{"furtherLink":{"label":"Explore bogi ni gone in Handbook of the Fijian Language (1893)","href":"https://theswissbay.ch/pdf/Books/Linguistics/Mega%20linguistics%20pack/Austronesian/Fijian%20Language%2C%20Handbook%20of%20the%20%28Moore%29%20%281893%29.pdf"},"quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"Historical page 20 describes the soft area where the skull bones have not closed. A second historical handbook gives the crown of the head. Anatomy and present-day use need review."}}', '[{"sourceId":"a2056948d246","page":20},{"sourceId":"bogi-moore"}]', '[]', 'bogi ni gone | the soft spot or crown of a young child’s head. | |', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('bona-stench-20261030', 'standard-fijian', 'word', 'bona', 'bona', 'noun', 'A foul smell or stench from something rotten.', '', '', '', 'Photographed historical page 22 lists a noun as well as a verb. A present-day example is needed before approval.', '{"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"Photographed historical page 22 lists a noun as well as a verb. A present-day example is needed before approval."}}', '[{"sourceId":"a2056948d246","page":22}]', '[]', 'bona | a foul smell or stench from something rotten. | |', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('bula-state-20261030', 'standard-fijian', 'word', 'bula', 'bula', 'descriptive word', 'Alive, healthy, or sound in body or mind; in tamata bula, a living or healthy person.', '', '', '', 'The pattern provides the phrase and several related senses. Context can also give a predicate use, already shown under the separate verb sense.', '{"role":{"fijian":"yavu","english":"lexical base in this description"},"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"The photographed page provides the phrase and several related senses. Context can also give a predicate use, already shown under the separate verb sense."}}', '[{"sourceId":"a2056948d246","page":24}]', '[]', 'bula | alive, healthy, or sound in body or mind; in tamata bula, a living or healthy person. | |', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
