INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('bula-greeting-20261030', 'standard-fijian', 'word', 'bula', 'bula', 'greeting', 'Hello! A greeting that carries a wish for life and good health.', '', '', '', 'University of the South Pacific explains the greeting and its connection to life and health. Ikurau classification is tentative until the team reviews an actual utterance.', '{"furtherLink":{"label":"Explore bula in University of the South Pacific · Say bula","href":"https://repository.usp.ac.fj/id/eprint/4668/"},"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"University of the South Pacific explains the greeting and its connection to life and health. Ikurau classification is tentative until the team reviews an actual utterance."}}', '[{"sourceId":"bula-usp"}]', '[]', 'bula | hello! a greeting that carries a wish for life and good health. | |', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
