INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('lade-attested-example-20261031', 'standard-fijian', 'word', 'lade', 'lade', 'verb', 'To jump or leap.', '', '', '', 'The sentence and word roles need fluent-speaker review.', '{"role":{"fijian":"vu","english":"predicate base: jump or leap"},"usageExamples":[{"fijian":"Era lade e na marau.","english":"They leap for joy.","words":[{"text":"Era","role":"durusau","abbr":"ds","english":"actor marker referring to several people"},{"text":"lade","role":"vu","abbr":"vu","english":"predicate base: jump or leap","focus":true},{"text":"e","role":"mata","abbr":"m","english":"first marker of the noun phrase"},{"text":"na","role":"mata","abbr":"m","english":"general noun-phrase marker"},{"text":"marau","role":"yavu","abbr":"y","english":"base of the noun phrase: joy"}]}],"furtherLink":{"label":"Explore lade in Hazlewood · A Fijian and English Dictionary (1890)","href":"https://upload.wikimedia.org/wikipedia/commons/8/80/A_Fijian_and_English_and_an_English_and_Fijian_dictionary%2C_with_examples_of_common_and_peculiar_modes_of_expression_and_uses_of_words%2C_also%2C_containing_brief_hints_on_native_customs_%28IA_fijianenglishand00hazl%29.pdf"},"quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"The sentence and ds · vu · m · m · y analysis come from the supplied scan. Online sources corroborate the two-marker pattern and natural use of lade ena marau. The exact role analysis and English rendering still need a fluent NAISEMA reviewer."}}', '[{"sourceId":"hazlewood-1890-lade"},{"sourceId":"tuvavosa-review-scan-2026-10-30","section":"3.2.3"},{"sourceId":"nanuma-lesu-12-online-mata"},{"sourceId":"fiji-times-lade-2015"}]', '["movement"]', 'lade | to jump or leap. | |', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
