INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('8eeb935117c0004f', 'standard-fijian', 'word', 'yau', 'yau', 'pronoun', 'I; me, according to its role in the phrase.', '', '', '', 'The nauni sosomi chart records yau as an independent form. The founder also confirms object use meaning me. Check a complete phrase before assigning a more specific matanauni role.', '{"relatedWords":["au"],"comparison":"Yau and au both refer to the speaker, and either can mean me in context. The independent use o yau does not make yau exclusively a subject form.","furtherLink":{"label":"Explore yau in ANU thesis: Standard Fijian pronoun paradigm (Table 7.2)","href":"https://openresearch-repository.anu.edu.au/bitstreams/ad8ffd53-3125-4166-885e-a761ec8bf989/download"},"quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"The nauni sosomi chart records yau as an independent form. The founder also confirms object use meaning me. Check a complete phrase before assigning a more specific matanauni role."}}', '[{"sourceId":"tuvavosa-review-scan-2026-10-30","section":"3.4.4"},{"sourceId":"fijian-pronoun-paradigm-study"},{"sourceId":"naisema-founder-au-yau-aua-auwa-2026-11-03"}]', '["pronouns"]', 'yau | i; me, according to its role in the phrase. | |', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
