INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('f03599fde855ccf9', 'standard-fijian', 'grammar-term', 'vei-', 'vei-', '', 'prefix that may form group or place related nouns', '', 'Attached before some nauni bases, vei- can form a collective or related place noun. Its exact meaning depends on the whole word and context; it has other uses elsewhere.', '', 'This explanation and its use in a complete Fijian phrase need team review.', '{"comparison":"This attached vei- may build a collective or place word. The separate vei can mark a relationship inside a phrase; identical spelling does not mean identical role.","grammarFunction":"prefix that may form group or place related nouns","grammarGroup":"Word building and roles","grammarExample":"veitacini","quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"Prefix pattern from the supplied scan. Review each derived lexeme separately; the prefix alone does not fix a word''s role."}}', '[{"sourceId":"tuvavosa-review-scan-2026-10-30","section":"3.4.2"}]', '[]', 'vei- | prefix that may form group or place related nouns | | attached before some nauni bases, vei- can form a collective or related place noun. its exact meaning depends on the whole word and context; it has other uses elsewhere.', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('834506b365e6196a', 'standard-fijian', 'grammar-term', 'dau-', 'dau-', '', 'prefix that may form a person noun for habitual or skilled activity', '', 'Attached before a vu or nauni base, dau- can name a person associated with an activity, often habitually or skillfully. Distinguish this bound prefix from the separate word dau (''often'').', '', 'This explanation and its use in a complete Fijian phrase need team review.', '{"comparison":"Attached dau- can form a person word associated with an activity. Separate dau can express habitual action in a matavu.","grammarFunction":"prefix that may form a person noun for habitual or skilled activity","grammarGroup":"Word building and roles","grammarExample":"dauqoli","quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"Prefix pattern from the supplied scan. Review each derived lexeme separately; the prefix alone does not fix a word''s role."}}', '[{"sourceId":"tuvavosa-review-scan-2026-10-30","section":"3.4.2"}]', '[]', 'dau- | prefix that may form a person noun for habitual or skilled activity | | attached before a vu or nauni base, dau- can name a person associated with an activity, often habitually or skillfully. distinguish this bound prefix from the separate word dau (''often'').', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('0e2c1e219d353907', 'standard-fijian', 'grammar-term', 'i-', 'i-', '', 'prefix that may derive a noun from a predicate base', '', 'Attached before some vu bases, i- may form a nauni raraba naming a tool, product, act, activity, place or remnant. Check each word individually; an initial i alone does not prove this analysis.', '', 'This explanation and its use in a complete Fijian phrase need team review.', '{"comparison":"Attached i- can derive a nominal word from a base. Separate i can link a named person in a taukeni kuri phrase.","grammarFunction":"prefix that may derive a noun from a predicate base","grammarGroup":"Word building and roles","grammarExample":"idabedabe","quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"Prefix pattern from the supplied scan. Review each derived lexeme separately; the prefix alone does not fix a word''s role."}}', '[{"sourceId":"tuvavosa-review-scan-2026-10-30","section":"3.4.2"}]', '[]', 'i- | prefix that may derive a noun from a predicate base | | attached before some vu bases, i- may form a nauni raraba naming a tool, product, act, activity, place or remnant. check each word individually; an initial i alone does not prove this analysis.', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
