INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('0a865965a74fbd1d', 'standard-fijian', 'grammar-term', 'matanauni taukeni', 'matanauni-taukeni', '', 'noun phrase expressing a possessive or related relationship', '', 'Taukeni is a component of a matanauni. For a named person (NY), its teaching pattern is na + yavu + optional kilanauni + t + i + NY. For a nonhuman common-noun base (NR), this pattern illustrates ni + NR after the yavu, as in na ulu ni vuaka. Pronoun owners use another pattern. Interpret the relationship from the phrase and context.', '', 'This explanation and its use in a complete Fijian phrase need team review.', '{"comparison":"A matanauni taukeni expresses a relation to an owner or other participant; a plain matanauni need not express that relation.","grammarFunction":"noun phrase expressing a possessive or related relationship","grammarGroup":"Noun phrase","grammarExample":"na ulu ni vuaka","tables":[{"title":"Matanauni taukeni · named-person relationships","columns":["Tuvavosa relationship","Marker before NY","Example from this pattern","What English needs to say"],"rows":[["Taukeni dina / raraba","nei","na vale nei Luke","Luke owns the house; with other bases, he may make or perform it"],["Taukeni bale","kei","na sere kei Lia","a song about Lia, or otherwise directed toward her"],["Taukeni kana","kei","na dalo kei Sami","taro for Sami to eat"],["Taukeni gunu","mei","na yaqona mei Tui","yaqona for Tui to drink"],["Taukeni kuri","i","na luve i Jo","Jo''s child; direct body-part and kinship relation"]],"note":"NY means nauni yaca (a named person). The same kei form may express bale or kana; decide from the yavu and the intended relationship. The example wording needs team review."},{"title":"Matanauni taukeni · common-noun relationships","columns":["Relationship to interpret","Marker before NR","Example in this pattern","Possible English reading"],"rows":[["Action or sound produced","ni","na kudru ni vuaka","the pig''s grunt"],["About the second noun","ni","na italanoa ni vuaka","a story about the pig"],["Intended for the second noun","ni","na moto ni vuaka","a spear for a pig"],["The second noun consumes the first","ni","na benu ni vuaka; na wai ni vuaka","refuse for the pig to eat; water for the pig to drink"],["Body-part relationship","ni","na ulu ni vuaka","the pig''s head"],["Offspring relationship","ni","na luve ni vuaka","the pig''s offspring"]],"note":"NR means nauni raraba (common-noun base). The phrase wording needs team review. Ni does not by itself tell you which English relationship to use. Na vale ni koli illustrates a nonhuman common-noun pattern; human common-noun owners need separate review."}],"furtherLink":{"label":"Explore matanauni taukeni in QMUL GLOW 42: Fijian possessive classifiers as nominal Appl heads","href":"https://glowlinguistics.org/42/wp-content/uploads/sites/4/2019/03/GLOW_FJPoss.pdf"},"quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"Source-led learning explanation. Check the exact Fijian phrase and the intended relationship before approval."}}', '[{"sourceId":"tuvavosa-review-scan-2026-10-30","section":"3.5.1-3.5.2"},{"sourceId":"qmul-fijian-possession-2019"},{"sourceId":"qmul-fijian-noun-phrase-2019"}]', '[]', 'matanauni taukeni | noun phrase expressing a possessive or related relationship | | taukeni is a component of a matanauni. for a named person (ny), its teaching pattern is na + yavu + optional kilanauni + t + i + ny. for a nonhuman common-noun base (nr), this pattern illustrates ni + nr after the yavu, as in na ulu ni vuaka. pronoun owners use another pattern. interpret the relationship from the phrase and context.', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('752836d417d96c2f', 'standard-fijian', 'grammar-term', 'taukeni dina', 'taukeni-dina', '', 'ownership or maker/performer relationship', '', 'Also called taukeni raraba in this pattern. For a named person, ne-i surfaces as nei. This can identify an owner or the person who made or performed what the yavu names; context decides.', '', 'This explanation and its use in a complete Fijian phrase need team review.', '{"comparison":"Taukeni dina can identify ownership or the maker or performer; taukeni bale identifies a topic or intended recipient. English ''X''s'' hides the difference.","searchKeywords":["taukeni raraba"],"grammarFunction":"ownership or maker/performer relationship","grammarGroup":"Noun phrase","grammarExample":"na sere nei Mere","furtherLink":{"label":"Explore taukeni dina in QMUL GLOW 42: Fijian possessive classifiers as nominal Appl heads","href":"https://glowlinguistics.org/42/wp-content/uploads/sites/4/2019/03/GLOW_FJPoss.pdf"},"quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"Source-led learning explanation. Check the exact Fijian phrase and the intended relationship before approval."}}', '[{"sourceId":"tuvavosa-review-scan-2026-10-30","section":"3.5.2"},{"sourceId":"qmul-fijian-possession-2019"}]', '[]', 'taukeni dina | ownership or maker/performer relationship | | also called taukeni raraba in this pattern. for a named person, ne-i surfaces as nei. this can identify an owner or the person who made or performed what the yavu names; context decides. | taukeni raraba', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('2dbb7f7fadd58c59', 'standard-fijian', 'grammar-term', 'taukeni bale', 'taukeni-bale', '', 'relationship about or directed toward a named person', '', 'For a named person, ke-i surfaces as kei. The yavu is about, for, or directed at that person; this does not by itself mean the person owns it. The same visible kei also occurs in taukeni kana.', '', 'This explanation and its use in a complete Fijian phrase need team review.', '{"comparison":"Taukeni bale concerns someone as a topic or intended recipient; taukeni kana identifies the one who will consume the food. Both can use kei before a name.","grammarFunction":"relationship about or directed toward a named person","grammarGroup":"Noun phrase","grammarExample":"na sere kei Lia","quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"Source-led learning explanation. Check the exact Fijian phrase and the intended relationship before approval."}}', '[{"sourceId":"tuvavosa-review-scan-2026-10-30","section":"3.5.2"}]', '[]', 'taukeni bale | relationship about or directed toward a named person | | for a named person, ke-i surfaces as kei. the yavu is about, for, or directed at that person; this does not by itself mean the person owns it. the same visible kei also occurs in taukeni kana.', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('5a5b694e0a17f397', 'standard-fijian', 'grammar-term', 'taukeni kana', 'taukeni-kana', '', 'food or consumable intended for a named person', '', 'For a named person, ke-i surfaces as kei. The named person is to eat or otherwise consume the yavu. This differs from nei when the person owns, grows, makes, or sells the same item.', '', 'This explanation and its use in a complete Fijian phrase need team review.', '{"comparison":"Taukeni kana identifies who will eat or consume something; taukeni gunu identifies who will drink it. The relation, not English ''my/his'', selects the pattern.","grammarFunction":"food or consumable intended for a named person","grammarGroup":"Noun phrase","grammarExample":"na dalo kei Sami","furtherLink":{"label":"Explore taukeni kana in QMUL GLOW 42: Fijian possessive classifiers as nominal Appl heads","href":"https://glowlinguistics.org/42/wp-content/uploads/sites/4/2019/03/GLOW_FJPoss.pdf"},"quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"Source-led learning explanation. Check the exact Fijian phrase and the intended relationship before approval."}}', '[{"sourceId":"tuvavosa-review-scan-2026-10-30","section":"3.5.2"},{"sourceId":"qmul-fijian-possession-2019"}]', '["food"]', 'taukeni kana | food or consumable intended for a named person | | for a named person, ke-i surfaces as kei. the named person is to eat or otherwise consume the yavu. this differs from nei when the person owns, grows, makes, or sells the same item.', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('3307f9b594dbe482', 'standard-fijian', 'grammar-term', 'taukeni gunu', 'taukeni-gunu', '', 'drink intended for a named person', '', 'For a named person, me-i surfaces as mei. The person is to drink the yavu. The same drink can use nei in a different relationship, such as owning or selling it.', '', 'This explanation and its use in a complete Fijian phrase need team review.', '{"comparison":"Taukeni gunu identifies who will drink something; taukeni kana identifies who will eat or consume it. Mei before a name differs from kei.","grammarFunction":"drink intended for a named person","grammarGroup":"Noun phrase","grammarExample":"na yaqona mei Tui","furtherLink":{"label":"Explore taukeni gunu in QMUL GLOW 42: Fijian possessive classifiers as nominal Appl heads","href":"https://glowlinguistics.org/42/wp-content/uploads/sites/4/2019/03/GLOW_FJPoss.pdf"},"quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"Source-led learning explanation. Check the exact Fijian phrase and the intended relationship before approval."}}', '[{"sourceId":"tuvavosa-review-scan-2026-10-30","section":"3.5.2"},{"sourceId":"qmul-fijian-possession-2019"}]', '["food"]', 'taukeni gunu | drink intended for a named person | | for a named person, me-i surfaces as mei. the person is to drink the yavu. the same drink can use nei in a different relationship, such as owning or selling it.', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('33ef7c87e675ce5a', 'standard-fijian', 'grammar-term', 'taukeni kuri', 'taukeni-kuri', '', 'direct relationship of a body part, kin member, or related part', '', 'Taukeni kuri is a direct relation such as a body part or kin term. For a named person, a linker i can follow the base: na luve i Jo. For an understood pronoun owner, a licensed kuri sosomi follows the base: na yavaqu. The new photo contrasts direct na luveikeimami with preposed na neimami gone and warns that some related bases require preposed possession or allow both patterns. Check the actual lexical base before choosing a form.', '', 'This explanation and its use in a complete Fijian phrase need team review.', '{"comparison":"Taukeni kuri links a body part, close kin, or related base directly to a person; taukeni dina uses a different ownership or performer relation.","grammarFunction":"direct relationship of a body part, kin member, or related part","grammarGroup":"Noun phrase","grammarExample":"Na yavaqu. / Na luve i Jo. / Na luveikeimami.","tables":[{"title":"Kuri sosomi · VR (attached person/number forms)","columns":["Wiliwili · number","Qo · speaker, listener excluded","Qori · listener","Ya · third person","Okati · speaker and listener"],"rows":[["Dua · one","-qu","-mu","-na","—"],["Rua · two","-irau","-mudrau","-drau","-daru"],["Vica · a few","-itou","-mudou","-dratou","-datou"],["Levu · many","-imami","-muni","-dra","-da"]],"note":"These attached forms show different person and number combinations. These are not independent nauni sosomi. The inclusive okati column has no singular. Team review is still required for example wording."}],"furtherLink":{"label":"Explore taukeni kuri in QMUL GLOW 42: Fijian possessive classifiers as nominal Appl heads","href":"https://glowlinguistics.org/42/wp-content/uploads/sites/4/2019/03/GLOW_FJPoss.pdf"},"quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"Source-led learning explanation. Check the exact Fijian phrase and the intended relationship before approval."}}', '[{"sourceId":"tuvavosa-review-scan-2026-10-30","section":"3.5.2-3.5.4"},{"sourceId":"qmul-fijian-possession-2019"},{"sourceId":"fijian-tama-i-jone-example"},{"sourceId":"tuvavosa-matanauni-set-01-photos-2026-10-31","section":"3.5.2–3.5.4; P03–P01"}]', '[]', 'taukeni kuri | direct relationship of a body part, kin member, or related part | | taukeni kuri is a direct relation such as a body part or kin term. for a named person, a linker i can follow the base: na luve i jo. for an understood pronoun owner, a licensed kuri sosomi follows the base: na yavaqu. the new photo contrasts direct na luveikeimami with preposed na neimami gone and warns that some related bases require preposed possession or allow both patterns. check the actual lexical base before choosing a form.', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('22741e4a1224b011', 'standard-fijian', 'grammar-term', 'nei', 'nei', '', 'taukeni dina/raraba marker before a named person', '', 'In this possessive pattern, ne- plus the named-person linker i appears as nei. It may mark ownership or the person who made or performed the yavu. This entry describes only that contextual use of nei.', '', 'This explanation and its use in a complete Fijian phrase need team review.', '{"comparison":"Nei before a name can mark taukeni dina; kei can mark taukeni bale or kana. The same English possessive apostrophe does not choose between them.","grammarFunction":"taukeni dina/raraba marker before a named person","grammarGroup":"Noun phrase","grammarExample":"na vale nei Luke","furtherLink":{"label":"Explore nei in QMUL GLOW 42: Fijian possessive classifiers as nominal Appl heads","href":"https://glowlinguistics.org/42/wp-content/uploads/sites/4/2019/03/GLOW_FJPoss.pdf"},"quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"Source-led learning explanation. Check the exact Fijian phrase and the intended relationship before approval."}}', '[{"sourceId":"tuvavosa-review-scan-2026-10-30","section":"3.5.2"},{"sourceId":"qmul-fijian-possession-2019"}]', '[]', 'nei | taukeni dina/raraba marker before a named person | | in this possessive pattern, ne- plus the named-person linker i appears as nei. it may mark ownership or the person who made or performed the yavu. this entry describes only that contextual use of nei.', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('4bc9edec6aad1f9b', 'standard-fijian', 'grammar-term', 'kei', 'kei', '', 'taukeni bale or kana marker before a named person', '', 'In these possessive patterns, ke- plus i appears as kei. It can mark a person the yavu concerns, or a person intended to consume the yavu; the relationship depends on the phrase. Kei has other roles elsewhere.', '', 'This explanation and its use in a complete Fijian phrase need team review.', '{"comparison":"Kei before a name can mark a topic, intended recipient, or food consumer; nei marks a different ownership or performer relation, and mei is used for drink.","grammarFunction":"taukeni bale or kana marker before a named person","grammarGroup":"Noun phrase","grammarExample":"na dalo kei Sami","furtherLink":{"label":"Explore kei in QMUL GLOW 42: Fijian possessive classifiers as nominal Appl heads","href":"https://glowlinguistics.org/42/wp-content/uploads/sites/4/2019/03/GLOW_FJPoss.pdf"},"quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"Source-led learning explanation. Check the exact Fijian phrase and the intended relationship before approval."}}', '[{"sourceId":"tuvavosa-review-scan-2026-10-30","section":"3.5.2"},{"sourceId":"qmul-fijian-possession-2019"}]', '[]', 'kei | taukeni bale or kana marker before a named person | | in these possessive patterns, ke- plus i appears as kei. it can mark a person the yavu concerns, or a person intended to consume the yavu; the relationship depends on the phrase. kei has other roles elsewhere.', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('41d0fd8be604af41', 'standard-fijian', 'grammar-term', 'mei', 'mei', '', 'taukeni gunu marker before a named person', '', 'In this possessive pattern, me- plus i appears as mei. It identifies the named person intended to drink the yavu. Mei may have other uses in other contexts.', '', 'This explanation and its use in a complete Fijian phrase need team review.', '{"comparison":"Mei before a name identifies the drink-related taukeni relation; kei covers topic or food-related relations in the patterns taught here.","grammarFunction":"taukeni gunu marker before a named person","grammarGroup":"Noun phrase","grammarExample":"na yaqona mei Tui","furtherLink":{"label":"Explore mei in QMUL GLOW 42: Fijian possessive classifiers as nominal Appl heads","href":"https://glowlinguistics.org/42/wp-content/uploads/sites/4/2019/03/GLOW_FJPoss.pdf"},"quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"Source-led learning explanation. Check the exact Fijian phrase and the intended relationship before approval."}}', '[{"sourceId":"tuvavosa-review-scan-2026-10-30","section":"3.5.2"},{"sourceId":"qmul-fijian-possession-2019"}]', '[]', 'mei | taukeni gunu marker before a named person | | in this possessive pattern, me- plus i appears as mei. it identifies the named person intended to drink the yavu. mei may have other uses in other contexts.', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('72722220b5a00107', 'standard-fijian', 'grammar-term', 'i', 'i', '', 'linker before a named person in taukeni kuri', '', 'In this direct possessive pattern, i links a relational yavu such as a kin term to the named person. In our teaching drafts, write it separately before the name; preserve the spelling of an original quotation. I has other roles elsewhere.', '', 'This explanation and its use in a complete Fijian phrase need team review.', '{"comparison":"Separate i can link a named person to a directly related base, as in na luve i Jo; attached i- can derive a new word. Check the spacing and phrase.","grammarFunction":"linker before a named person in taukeni kuri","grammarGroup":"Noun phrase","grammarExample":"na luve i Jo","furtherLink":{"label":"Explore i in QMUL GLOW 42: Fijian possessive classifiers as nominal Appl heads","href":"https://glowlinguistics.org/42/wp-content/uploads/sites/4/2019/03/GLOW_FJPoss.pdf"},"quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"Source-led learning explanation. Check the exact Fijian phrase and the intended relationship before approval."}}', '[{"sourceId":"tuvavosa-review-scan-2026-10-30","section":"3.5.2"},{"sourceId":"qmul-fijian-possession-2019"},{"sourceId":"fijian-tama-i-jone-example"}]', '[]', 'i | linker before a named person in taukeni kuri | | in this direct possessive pattern, i links a relational yavu such as a kin term to the named person. in our teaching drafts, write it separately before the name; preserve the spelling of an original quotation. i has other roles elsewhere.', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('b2448328cae9ae21', 'standard-fijian', 'grammar-term', 'ni', 'ni', '', 'linker before a common-noun base in this taukeni pattern', '', 'This pattern places ni between the first yavu and a nonhuman nauni raraba (NR), as in na ulu ni vuaka. The same ni can introduce different relationships such as sound, topic, intended use, food or drink, body part, and offspring. Ni has other grammatical roles elsewhere; do not assign this role without its full phrase. Human common-noun patterns require separate review.', '', 'This explanation and its use in a complete Fijian phrase need team review.', '{"comparison":"Ni links a common-noun base in this taukeni pattern; nei, kei, and mei link named people in different relationships.","grammarFunction":"linker before a common-noun base in this taukeni pattern","grammarGroup":"Noun phrase","grammarExample":"na ulu ni vuaka","furtherLink":{"label":"Explore ni in QMUL GLOW 42: Fijian possessive classifiers as nominal Appl heads","href":"https://glowlinguistics.org/42/wp-content/uploads/sites/4/2019/03/GLOW_FJPoss.pdf"},"quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"Source-led learning explanation. Check the exact Fijian phrase and the intended relationship before approval."}}', '[{"sourceId":"tuvavosa-review-scan-2026-10-30","section":"3.5.2"},{"sourceId":"qmul-fijian-possession-2019"}]', '[]', 'ni | linker before a common-noun base in this taukeni pattern | | this pattern places ni between the first yavu and a nonhuman nauni raraba (nr), as in na ulu ni vuaka. the same ni can introduce different relationships such as sound, topic, intended use, food or drink, body part, and offspring. ni has other grammatical roles elsewhere; do not assign this role without its full phrase. human common-noun patterns require separate review.', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('b7c0345bbe136ca9', 'standard-fijian', 'grammar-term', 'no-/ne-', 'no-ne-', '', 'ikuri taukeni for a general ownership or related action', '', 'In taukeni sosomi, this first bound element joins a kuri sosomi before the yavu, as in no- + -mu to make nomu. Other examples include neimami. This is taukeni dina/raraba, not the postposed taukeni kuri order.', '', 'This explanation and its use in a complete Fijian phrase need team review.', '{"comparison":"No-/ne- marks a general ownership or related-action relationship before an attached person ending; ke- and me- select different relations.","grammarFunction":"ikuri taukeni for a general ownership or related action","grammarGroup":"Word building and roles","grammarExample":"na nomu lako","furtherLink":{"label":"Explore no-/ne- in QMUL GLOW 42: Fijian possessive classifiers as nominal Appl heads","href":"https://glowlinguistics.org/42/wp-content/uploads/sites/4/2019/03/GLOW_FJPoss.pdf"},"quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"Source-led learning explanation. Check the exact Fijian phrase and the intended relationship before approval."}}', '[{"sourceId":"tuvavosa-review-scan-2026-10-30","section":"3.5.3"},{"sourceId":"qmul-fijian-possession-2019"}]', '[]', 'no-/ne- | ikuri taukeni for a general ownership or related action | | in taukeni sosomi, this first bound element joins a kuri sosomi before the yavu, as in no- + -mu to make nomu. other examples include neimami. this is taukeni dina/raraba, not the postposed taukeni kuri order.', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('2055c67eb2b22204', 'standard-fijian', 'grammar-term', 'ke-', 'ke-', '', 'ikuri taukeni for bale or kana relationships', '', 'In taukeni sosomi, ke- joins a kuri sosomi before the yavu. Examples include na kena italanoa for a topic-related reading and na keimami uvi for food intended for a group. The same ke- does not by itself identify which relationship applies.', '', 'This explanation and its use in a complete Fijian phrase need team review.', '{"comparison":"Ke- can mark a topic or food relationship before an attached person ending; no-/ne- and me- select other relations.","grammarFunction":"ikuri taukeni for bale or kana relationships","grammarGroup":"Word building and roles","grammarExample":"na keimami uvi","furtherLink":{"label":"Explore ke- in QMUL GLOW 42: Fijian possessive classifiers as nominal Appl heads","href":"https://glowlinguistics.org/42/wp-content/uploads/sites/4/2019/03/GLOW_FJPoss.pdf"},"quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"Source-led learning explanation. Check the exact Fijian phrase and the intended relationship before approval."}}', '[{"sourceId":"tuvavosa-review-scan-2026-10-30","section":"3.5.3"},{"sourceId":"qmul-fijian-possession-2019"}]', '[]', 'ke- | ikuri taukeni for bale or kana relationships | | in taukeni sosomi, ke- joins a kuri sosomi before the yavu. examples include na kena italanoa for a topic-related reading and na keimami uvi for food intended for a group. the same ke- does not by itself identify which relationship applies.', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('18e514d149329644', 'standard-fijian', 'grammar-term', 'me-', 'me-', '', 'ikuri taukeni for a drink intended for someone', '', 'In taukeni sosomi, me- joins a kuri sosomi before the yavu. Examples include na memudou ti. The marker precedes the drink base, unlike the suffix-after-base order of taukeni kuri.', '', 'This explanation and its use in a complete Fijian phrase need team review.', '{"comparison":"Me- marks a drink relationship before an attached person ending; ke- can be used for food or a topic.","grammarFunction":"ikuri taukeni for a drink intended for someone","grammarGroup":"Word building and roles","grammarExample":"na memudou ti","furtherLink":{"label":"Explore me- in QMUL GLOW 42: Fijian possessive classifiers as nominal Appl heads","href":"https://glowlinguistics.org/42/wp-content/uploads/sites/4/2019/03/GLOW_FJPoss.pdf"},"quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"Source-led learning explanation. Check the exact Fijian phrase and the intended relationship before approval."}}', '[{"sourceId":"tuvavosa-review-scan-2026-10-30","section":"3.5.3"},{"sourceId":"qmul-fijian-possession-2019"}]', '[]', 'me- | ikuri taukeni for a drink intended for someone | | in taukeni sosomi, me- joins a kuri sosomi before the yavu. examples include na memudou ti. the marker precedes the drink base, unlike the suffix-after-base order of taukeni kuri.', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('de665fe8c0ac0af4', 'standard-fijian', 'grammar-term', 'yavu ni matavu', 'yavu-ni-matavu', '', 'The meaning-bearing core of a matavu; it may be a vu or, in context, a nauni.', '', 'In au ā qasenivuli tū kina, qasenivuli is the core of the predicate phrase.', '', 'This explanation and its use in a complete Fijian phrase need team review.', '{"comparison":"A yavu ni matavu is the core only of a predicate phrase. Yavu is the wider label for the lexical base of a matavosa.","grammarFunction":"The meaning-bearing core of a matavu; it may be a vu or, in context, a nauni.","grammarGroup":"Predicate phrase","grammarExample":"au ā qasenivuli tū kina","quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"Provisional paraphrase from a user-supplied page photo. Exact spelling, sense, and phrase role need team review; the source title and author are not yet identified."}}', '[{"sourceId":"tuvavosa-4-3-photos-2026-10-31","section":"4.3.1"}]', '[]', 'yavu ni matavu | the meaning-bearing core of a matavu; it may be a vu or, in context, a nauni. | | in au a qasenivuli tu kina, qasenivuli is the core of the predicate phrase.', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('816296c42d58d423', 'standard-fijian', 'grammar-term', 'vei-', 'vei-', '', 'vei- can show that two participants do the action toward one another.', '', 'The reciprocal reading depends on both the base and the participants; rau sā veidomoni describes Jo and Lo loving one another.', '', 'This explanation and its use in a complete Fijian phrase need team review.', '{"comparison":"Compare this with vei- that names an activity without stating its affected thing, as in e veicula o nasi.","grammarFunction":"vei- can show that two participants do the action toward one another.","grammarGroup":"Word building and roles","grammarExample":"rau sā veidomoni o Jo kei Lo","appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"Provisional paraphrase from a user-supplied page photo. Exact spelling, sense, and phrase role need team review; the source title and author are not yet identified."}}', '[{"sourceId":"tuvavosa-4-3-photos-2026-10-31","section":"4.3.2"}]', '[]', 'vei- | vei- can show that two participants do the action toward one another. | | the reciprocal reading depends on both the base and the participants; rau sa veidomoni describes jo and lo loving one another.', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('b71a9be5864ae0e5', 'standard-fijian', 'grammar-term', 'vei-', 'vei-', '', 'vei- can form a predicate that names an activity without stating its affected thing.', '', 'E veicula o nasi tells us about Nasi’s sewing activity; it does not name the item sewn.', '', 'This explanation and its use in a complete Fijian phrase need team review.', '{"comparison":"This differs from reciprocal vei-, which describes an action exchanged between participants.","grammarFunction":"vei- can form a predicate that names an activity without stating its affected thing.","grammarGroup":"Word building and roles","grammarExample":"e veicula o nasi","appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"Provisional paraphrase from a user-supplied page photo. Exact spelling, sense, and phrase role need team review; the source title and author are not yet identified."}}', '[{"sourceId":"tuvavosa-4-3-photos-2026-10-31","section":"4.3.2"}]', '[]', 'vei- | vei- can form a predicate that names an activity without stating its affected thing. | | e veicula o nasi tells us about nasi’s sewing activity; it does not name the item sewn.', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('0dafe55c2b62328e', 'standard-fijian', 'grammar-term', 'vei-', 'vei-', '', 'vei- can describe several people doing an activity together.', '', 'The prefix may give a collective reading when the context supplies a group. It does not always mean that each person acts on another.', '', 'This explanation and its use in a complete Fijian phrase need team review.', '{"comparison":"Reciprocal vei- describes action exchanged between participants; this use describes participation in a shared activity.","grammarFunction":"vei- can describe several people doing an activity together.","grammarGroup":"Word building and roles","grammarExample":"era veidredrevaki","appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"Provisional paraphrase from a user-supplied page photo. Exact spelling, sense, and phrase role need team review; the source title and author are not yet identified."}}', '[{"sourceId":"tuvavosa-4-3-photos-2026-10-31","section":"4.3.2"}]', '[]', 'vei- | vei- can describe several people doing an activity together. | | the prefix may give a collective reading when the context supplies a group. it does not always mean that each person acts on another.', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('fdaeec6e318e466b', 'standard-fijian', 'grammar-term', 'vei-', 'vei-', '', 'vei- with a kinship base can form a word for people related to one another.', '', 'In veitacini, the word names siblings as a relationship group; some kinship forms also end in -ni.', '', 'This explanation and its use in a complete Fijian phrase need team review.', '{"comparison":"This is a kinship noun, unlike reciprocal vei- used to describe an action.","grammarFunction":"vei- with a kinship base can form a word for people related to one another.","grammarGroup":"Word building and roles","grammarExample":"veitacini","appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"Provisional paraphrase from a user-supplied page photo. Exact spelling, sense, and phrase role need team review; the source title and author are not yet identified."}}', '[{"sourceId":"tuvavosa-4-3-photos-2026-10-31","section":"4.3.2"}]', '[]', 'vei- | vei- with a kinship base can form a word for people related to one another. | | in veitacini, the word names siblings as a relationship group; some kinship forms also end in -ni.', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('ad2fe9834a1a29a9', 'standard-fijian', 'grammar-term', 'vaka-', 'vaka-', '', 'vaka- can make a predicate meaning “cause to become or do” the base.', '', 'For this use, the result or action named by the base is brought about by someone or something else.', '', 'This explanation and its use in a complete Fijian phrase need team review.', '{"comparison":"Other uses of vaka- express manner, counting, pretense, or intensity; the whole word determines the reading.","grammarFunction":"vaka- can make a predicate meaning “cause to become or do” the base.","grammarGroup":"Word building and roles","grammarExample":"vakarogoya","quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"Provisional paraphrase from a user-supplied page photo. Exact spelling, sense, and phrase role need team review; the source title and author are not yet identified."}}', '[{"sourceId":"tuvavosa-4-3-photos-2026-10-31","section":"4.3.3"}]', '[]', 'vaka- | vaka- can make a predicate meaning “cause to become or do” the base. | | for this use, the result or action named by the base is brought about by someone or something else.', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
