--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('483e80aec9e36d82', 'standard-fijian', 'grammar-term', 'vaka-', 'vaka-', '', 'vaka- can express acting as though a state or role were real.', '', 'The derived form may mean that a person pretends to have the quality or role named by the base.', '', 'This explanation and its use in a complete Fijian phrase need team review.', '{"comparison":"This is different from a causative use, where someone actually brings about a state.","grammarFunction":"vaka- can express acting as though a state or role were real.","grammarGroup":"Word building and roles","appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"Provisional paraphrase from a user-supplied page photo. Exact spelling, sense, and phrase role need team review; the source title and author are not yet identified."}}', '[{"sourceId":"tuvavosa-4-3-photos-2026-10-31","section":"4.3.3"}]', '[]', 'vaka- | vaka- can express acting as though a state or role were real. | | the derived form may mean that a person pretends to have the quality or role named by the base.', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('0a272a29517e1d74', 'standard-fijian', 'grammar-term', 'vaka-', 'vaka-', '', 'vaka- can turn a nauni base into a predicate about having or using it.', '', 'In one use, vakavale can describe having a house; the specific meaning depends on the complete word and sentence.', '', 'This explanation and its use in a complete Fijian phrase need team review.', '{"comparison":"This is word formation from a nauni base, rather than a simple noun phrase containing that noun.","grammarFunction":"vaka- can turn a nauni base into a predicate about having or using it.","grammarGroup":"Word building and roles","grammarExample":"vakavale tiko nona vale","appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"Provisional paraphrase from a user-supplied page photo. Exact spelling, sense, and phrase role need team review; the source title and author are not yet identified."}}', '[{"sourceId":"tuvavosa-4-3-photos-2026-10-31","section":"4.3.3"}]', '[]', 'vaka- | vaka- can turn a nauni base into a predicate about having or using it. | | in one use, vakavale can describe having a house; the specific meaning depends on the complete word and sentence.', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
