--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('3e633dfb3372df18', 'standard-fijian', 'grammar-term', 'vaka-', 'vaka-', '', 'vaka- can form a predicate for saying or presenting a quoted expression.', '', 'With a suitable base, this use introduces the act of saying the quoted words.', '', 'This explanation and its use in a complete Fijian phrase need team review.', '{"comparison":"Do not assign a speech meaning to every vaka- word; compare its causative and manner uses.","grammarFunction":"vaka- can form a predicate for saying or presenting a quoted expression.","grammarGroup":"Word building and roles","grammarExample":"vakalasuya","appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"Provisional paraphrase from a user-supplied page photo. Exact spelling, sense, and phrase role need team review; the source title and author are not yet identified."}}', '[{"sourceId":"tuvavosa-4-3-photos-2026-10-31","section":"4.3.3"}]', '[]', 'vaka- | vaka- can form a predicate for saying or presenting a quoted expression. | | with a suitable base, this use introduces the act of saying the quoted words.', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('d744beea71bf4933', 'standard-fijian', 'grammar-term', 'lau-', 'lau-', '', 'lau- can place the affected person or thing in focus while leaving the actor unstated.', '', 'Laukana describes being eaten without naming who ate it. This is a participant pattern, not a general time marker.', '', 'This explanation and its use in a complete Fijian phrase need team review.', '{"comparison":"Reciprocal vei- describes participants acting toward one another; lau- here leaves the actor unexpressed.","grammarFunction":"lau- can place the affected person or thing in focus while leaving the actor unstated.","grammarGroup":"Word building and roles","grammarExample":"laukana","quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"Provisional paraphrase from a user-supplied page photo. Exact spelling, sense, and phrase role need team review; the source title and author are not yet identified."}}', '[{"sourceId":"tuvavosa-4-3-photos-2026-10-31","section":"4.3.4"}]', '[]', 'lau- | lau- can place the affected person or thing in focus while leaving the actor unstated. | | laukana describes being eaten without naming who ate it. this is a participant pattern, not a general time marker.', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('918adc55bba604a9', 'standard-fijian', 'grammar-term', 'lau-', 'lau-', '', 'lau- can describe an unwanted or harmful event affecting someone.', '', 'In some words the prefix contributes an adverse-event reading; the exact meaning depends on the base.', '', 'This explanation and its use in a complete Fijian phrase need team review.', '{"comparison":"This is an additional use of lau-, alongside the affected-participant pattern.","grammarFunction":"lau- can describe an unwanted or harmful event affecting someone.","grammarGroup":"Word building and roles","grammarExample":"lautā","appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"Provisional paraphrase from a user-supplied page photo. Exact spelling, sense, and phrase role need team review; the source title and author are not yet identified."}}', '[{"sourceId":"tuvavosa-4-3-photos-2026-10-31","section":"4.3.4"}]', '[]', 'lau- | lau- can describe an unwanted or harmful event affecting someone. | | in some words the prefix contributes an adverse-event reading; the exact meaning depends on the base.', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
