INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('51a26bb9c7e85582', 'standard-fijian', 'grammar-term', 'uto-', 'uto-', '', 'The core of a matavosa: its lexical base together with any attached word-building elements.', '', 'Uto identifies the central word form, including its yavu and any attached ikuri.', '', 'Paraphrased from a user-supplied printed-page photo (A01); publication details, spelling and application remain under review.', '{"comparison":"A separate duru surrounds the core in a phrase; an ikuri is attached within the core.","grammarFunction":"The core of a matavosa: its lexical base together with any attached word-building elements.","grammarGroup":"Predicate phrase","grammarExample":"yavu + ikuri","quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"Paraphrased from a user-supplied printed-page photo (A01); publication details, spelling and application remain under review."}}', '[{"sourceId":"tuvavosa-4-4-4-5-photos-2026-10-31","section":"4.3 glossary"}]', '[]', 'uto- | the core of a matavosa: its lexical base together with any attached word-building elements. | | uto identifies the central word form, including its yavu and any attached ikuri.', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
