--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('1c7b40b82d48c7a0', 'standard-fijian', 'grammar-term', 'vakalevu', 'vakalevu', '', 'An intensified meaning produced by some repeated or derived predicate forms.', '', 'The stronger meaning belongs to the complete form; repetition by itself does not always mean “very.”', '', 'Paraphrased from a user-supplied printed-page photo (A01); publication details, spelling and application remain under review.', '{"comparison":"Compare drua, which names the form-building process rather than the resulting degree of meaning.","grammarFunction":"An intensified meaning produced by some repeated or derived predicate forms.","grammarGroup":"Word building and roles","grammarExample":"rogorogoca","quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"Paraphrased from a user-supplied printed-page photo (A01); publication details, spelling and application remain under review."}}', '[{"sourceId":"tuvavosa-4-4-4-5-photos-2026-10-31","section":"4.3 glossary"}]', '[]', 'vakalevu | an intensified meaning produced by some repeated or derived predicate forms. | | the stronger meaning belongs to the complete form; repetition by itself does not always mean “very.”', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('840464ab04958abc', 'standard-fijian', 'grammar-term', 'veitabui', 'veitabui', '', 'A restriction that prevents two particular forms or roles from occurring together.', '', 'Use this label only when a specific construction excludes one combination; it is not a general label for rare words.', '', 'Paraphrased from a user-supplied printed-page photo (B01); publication details, spelling and application remain under review.', '{"comparison":"Lawa cocoko is a relatively fixed pattern; veitabui names a particular prohibited combination.","grammarFunction":"A restriction that prevents two particular forms or roles from occurring together.","grammarGroup":"Word building and roles","quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"Paraphrased from a user-supplied printed-page photo (B01); publication details, spelling and application remain under review."}}', '[{"sourceId":"tuvavosa-4-4-4-5-photos-2026-10-31","section":"4.5 glossary"}]', '[]', 'veitabui | a restriction that prevents two particular forms or roles from occurring together. | | use this label only when a specific construction excludes one combination; it is not a general label for rare words.', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
