INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('040f732cf6b4cdf0', 'standard-fijian', 'grammar-term', 'kuri sosomi', 'kuri-sosomi', '', 'attached person and number form used in possession', '', 'Ikuri sosomi (kuri sosomi) is an attached person-and-number ending. In neitou, ne- joins exclusive -itou; in nodatou, no- joins inclusive -datou. In wekadatou, -datou follows the nominal base weka. The attached ending is a different use from an independent nauni sosomi or a separate shortened pronoun form; the preceding base or possessive element determines the construction.', '', 'Paraphrased from the user''s private photographed Tuvavosa section; full form and spelling need team review.', '{"comparison":"Neitou contains exclusive -itou; nodatou and wekadatou contain inclusive -datou. Free tou and attached -itou must not be treated as the same form.","grammarFunction":"attached person and number form used in possession","grammarGroup":"Noun phrase","grammarExample":"neitou = ne- + -itou; nodatou = no- + -datou; wekadatou = weka + -datou","furtherLink":{"label":"Explore kuri sosomi in ANU thesis: Standard Fijian pronoun paradigm (Table 7.2)","href":"https://openresearch-repository.anu.edu.au/bitstreams/ad8ffd53-3125-4166-885e-a761ec8bf989/download"},"quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"Paraphrased from the user''s private photographed Tuvavosa section; full form and spelling need team review."}}', '[{"sourceId":"tuvavosa-matanauni-set-01-photos-2026-10-31","section":"3.5.3; P02"},{"sourceId":"naisema-founder-pronouns-2026-11-01"},{"sourceId":"fijian-pronoun-paradigm-study"},{"sourceId":"fijian-wekadatou-acts-15-1864"}]', '[]', 'kuri sosomi | attached person and number form used in possession | | ikuri sosomi (kuri sosomi) is an attached person-and-number ending. in neitou, ne- joins exclusive -itou; in nodatou, no- joins inclusive -datou. in wekadatou, -datou follows the nominal base weka. the attached ending is a different use from an independent nauni sosomi or a separate shortened pronoun form; the preceding base or possessive element determines the construction.', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('e358783c55f2d705', 'standard-fijian', 'word', 'saku vorowaqa', 'saku-vorowaqa', 'noun', 'Swordfish (Xiphias gladius), a large ocean fish with a long, flat bill.', '', '', '', 'Check this meaning and its use in a complete Fijian phrase before approving it.', '{"searchKeywords":["Fijian fish","marine fish","seafood","saku-voro-waqa"],"exploration":{"title":"A name that points to its shape","text":"Saku vorowaqa names the swordfish, Xiphias gladius. Its long, flat bill is the identifying detail in this sense.","question":"Which feature would you check before calling a long-billed fish saku vorowaqa?"},"furtherLink":{"label":"Explore saku vorowaqa in Auckland Museum · Navakavu fish names (2024)","href":"https://www.aucklandmuseum.com/discover/stories/blog/2024/sharing-biodiversity-records-in-fiji"},"quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"Owner correction and independent Navakavu records support swordfish. Gatty and another fisheries list use the same name for sailfish. Keep the variation visible for review."}}', '[{"sourceId":"auckland-museum-navakavu-swordfish-2024"},{"sourceId":"fishbase-fiji-swordfish-saku-vorowaqa"}]', '["fiji-fish","sea-life"]', 'saku vorowaqa | swordfish (xiphias gladius), a large ocean fish with a long, flat bill. | | | fijian fish | marine fish | seafood | saku-voro-waqa', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('048ae62227bafc1b', 'standard-fijian', 'grammar-term', 'ikurisosomi', 'ikurisosomi', '', 'possessive suffix attached to a noun', '', 'A following element on a noun that marks whose it is; the workbook lists forms such as -qu, -mu, and -na.', '', 'Spelling checked against the cited page; short English meaning needs speaker review.', '{"comparison":"Ikurisosomi here names a possessive ending on a nominal base; ikuri sosomi is the wider attached person-and-number form. Check the exact spelling and construction.","searchKeywords":["ikuritaukeni"],"grammarFunction":"possessive suffix attached to a noun","grammarGroup":"Word building and roles","grammarExample":"tamaqu","quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"Spelling checked against the cited page; short English meaning needs speaker review."}}', '[{"sourceId":"7c18e6d64894","page":80}]', '[]', 'ikurisosomi | possessive suffix attached to a noun | | a following element on a noun that marks whose it is; the workbook lists forms such as -qu, -mu, and -na. | ikuritaukeni', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
