INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('f6d9eba99fde95a9', 'standard-fijian', 'word', 'kawakawa', 'kawakawa', 'noun', 'Grouper; the name is used for several related reef fish.', '', '', '', 'Independent English draft. The Fiji Ministry of Fisheries poster lists multiple species as kawakawa; WCS gives a specific example. No single scientific name applies to this broad entry. NAISEMA team review is pending.', '{"comparison":"Ika means fish generally; kawakawa is a grouper name used for several species.","searchKeywords":["Fijian fish","marine fish","seafood"],"furtherLink":{"label":"Explore kawakawa in Fiji Ministry of Fisheries grouper poster in FAO field manual","href":"https://www.fao.org/fileadmin/templates/ess/ess_test_folder/World_Census_Agriculture/WCA_2020/WCA_2020_new_doc/FIJ_MAN_ENG_2020.pdf"},"quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"Independent English draft. The Fiji Ministry of Fisheries poster lists multiple species as kawakawa; WCS gives a specific example. No single scientific name applies to this broad entry. NAISEMA team review is pending."}}', '[{"sourceId":"fiji-fisheries-grouper-poster"},{"sourceId":"wcs-fiji-groupers"}]', '["fiji-fish","sea-life"]', 'kawakawa | grouper; the name is used for several related reef fish. | | | fijian fish | marine fish | seafood', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
