INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('2d45c42e5b08c297', 'standard-fijian', 'word', 'balolo', 'balolo', 'noun', 'An edible marine worm that appears in seasonal swarms around some Pacific reefs; identified in Fiji as Eunice viridis.', '', '', '', 'Independent English draft. The scientific report identifies balolo in Fiji; the USP account independently documents its seasonal food use. The original extracted definition was cut off; this is newly written English and remains subject to speaker review. NAISEMA team review is pending.', '{"scientificName":"Eunice viridis","identificationNote":"The USP account records the Fijian seasonal phrases vula i balolo lalai and vula i balolo levu. Confirm local usage before assigning a fixed Tuvavosa role.","furtherLink":{"label":"Explore balolo in Japanese Journal of Benthology, report on balolo in Fiji","href":"https://www.jstage.jst.go.jp/article/benthos/79/1/79_79/_article/-char/en"},"quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"Independent English draft. The scientific report identifies balolo in Fiji; the USP account independently documents its seasonal food use. The original extracted definition was cut off; this is newly written English and remains subject to speaker review. NAISEMA team review is pending."}}', '[{"sourceId":"benthos-balolo-fiji-2024"},{"sourceId":"usp-fiji-seasonal-foods-balolo"}]', '[]', 'balolo | an edible marine worm that appears in seasonal swarms around some pacific reefs; identified in fiji as eunice viridis. | |', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
