INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('c6f2d5b78f6063c5', 'standard-fijian', 'word', 'balawa', 'balawa', 'noun', 'Fruit from the balawa screw pine; in some contexts, the name can also refer to a pineapple.', '', '', '', 'Independent English draft. JICA and USP confirm balawa as pandanus; FAO records the pineapple use. A speaker should confirm when balawa names the fruit rather than the plant. NAISEMA team review is pending.', '{"furtherLink":{"label":"Explore balawa in JICA · Fiji study report","href":"https://openjicareport.jica.go.jp/pdf/12263562_05.pdf"},"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"Independent English draft. JICA and USP confirm balawa as pandanus; FAO records the pineapple use. A speaker should confirm when balawa names the fruit rather than the plant. NAISEMA team review is pending."}}', '[{"sourceId":"balawa-jica"},{"sourceId":"balawa-fao"},{"sourceId":"balawa-usp"}]', '["plants"]', 'balawa | fruit from the balawa screw pine; in some contexts, the name can also refer to a pineapple. | |', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
