INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('c7ba54f528e2baa3', 'standard-fijian', 'grammar-term', 'ikuri', 'ikuri', '', 'A part attached to a yavu to make a related word, such as vei- before a base or a dewa ending after it.', '', 'A short element joined to a base to change its meaning; the workbook distinguishes elements before and after the base.', '', 'Spelling checked against the cited page; short English meaning needs speaker review.', '{"comparison":"Ikuriliu comes before the base; ikurimuri comes after it. Unlike a separate duru, an ikuri attaches to the word.","grammarFunction":"A part attached to a yavu to make a related word, such as vei- before a base or a dewa ending after it.","grammarGroup":"Word building and roles","grammarExample":"vei-dredrevaki","quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"Spelling checked against the cited page; short English meaning needs speaker review."}}', '[{"sourceId":"7c18e6d64894","page":64}]', '[]', 'ikuri | a part attached to a yavu to make a related word, such as vei- before a base or a dewa ending after it. | | a short element joined to a base to change its meaning; the workbook distinguishes elements before and after the base.', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
